--[[---------------------------------------------------------------------------
	Advanced Material Editor - translated long-form parameter help

	Keep VMT parameter names, paths and numeric examples literal.  These tables
	mirror every entry in AdvMat.HELP; cl_20_help.lua falls back to the generic
	localised synopsis only for parameters which have no long-form entry.
-----------------------------------------------------------------------------]]

AdvMat = AdvMat or {}

AdvMat.HELP_I18N = {
	zh = {
		[ "$basetexture" ] = [[表面的主要颜色图像，也就是“油漆”而不是形状；这里的其他效果都会叠加在它上面。路径从 materials/ 目录内开始，并省略扩展名，例如 materials/models/kleiner/kleiner_sheet.vtf 应写成 models/kleiner/kleiner_sheet。它的 Alpha 通道会被共用：除非另行指定，透明度、Phong 遮罩和反射遮罩都会读取它。]],
		[ "$frame" ] = [[指定动画纹理从哪一帧开始。只有 .vtf 实际包含多帧时才有效；普通单帧纹理会忽略此项。]],
		[ "$model" ] = [[标记此材质属于模型而不是地图几何体。本编辑器创建的材质会自动启用它；关闭后通常会导致表面渲染错误。]],
		[ "$surfaceprop" ] = [[指定物理材质：被射击时的声音和粒子，以及表面的摩擦程度。可尝试 metal、flesh、glass、wood、dirt。它只影响游戏行为，不会改变外观。]],
		[ "$color2" ] = [[为整个材质着色。[1 1 1] 保持原样；[1 0.5 0.5] 保留红色并将绿色和蓝色减半，从而产生红色色调。大于 1 的值会提亮。模型通常应使用此着色，因为它在光照后应用，阴影仍会保留。]],
		[ "$color" ] = [[较旧的着色方式，在光照前应用，因此容易让表面显得发白。对模型而言 $color2 通常效果更好；仅当 $color2 没有效果时才使用它。]],
		[ "$blendtintbybasealpha" ] = [[把 $color2 限制在纹理 Alpha 为白色的区域。队伍颜色通常这样制作：在 Alpha 通道画出遮罩，只有该区域会着色。它会占用 Alpha 通道，因此不能与依赖 Alpha 的透明效果同时使用。]],
		[ "$blendtintcoloroverbase" ] = [[控制遮罩区域内色调与原纹理的混合方式。0 会把色调与纹理相乘并保留细节；1 会用纯色替换纹理；中间值在两者之间过渡。]],
		[ "$desaturatewithbasealpha" ] = [[根据纹理自身的 Alpha 通道去除颜色。0 保持原样，1 会把遮罩区域变成灰度。]],
		[ "$translucent" ] = [[使用 $basetexture 的 Alpha 通道让表面半透明：黑色 Alpha 完全不可见，白色完全不透明，灰色介于两者之间。注意排序问题：引擎把每个半透明表面作为整体绘制，同一模型的多个半透明部件可能顺序错误并呈现“里外颠倒”。头发、树叶、铁丝网等硬边缘对象应改用 $alphatest；它开销更低且排序正确。]],
		[ "$alphatest" ] = [[硬边透明：由 $basetexture 的 Alpha 通道决定每个像素完全显示或完全消失，不存在半透明。头发、植物、栅格和布料镂空几乎都应使用它；排序正确，开销也远低于 $translucent。]],
		[ "$alphatestreference" ] = [[设置 $alphatest 的截断值。像素的 Alpha 高于此值才会保留；较低的值保留更多纹理，较高的值裁掉更多。通常从 0.5 开始；头发像被啃掉时降到约 0.3，边缘有残留光晕时则提高。]],
		[ "$allowalphatocoverage" ] = [[利用游戏的抗锯齿淡化 $alphatest 留下的硬边。只有玩家启用 MSAA 时才有效。]],
		[ "$additive" ] = [[把材质颜色加到背景上，而不是覆盖背景。黑色会完全不可见，明亮区域会发光。适合火焰、能量、全息影像和玻璃高光，不适合应当显得不透明的物体。]],
		[ "$alpha" ] = [[均匀淡化整个材质：1 完全显示，0 完全不可见。与 $translucent 不同，它不读取纹理的 Alpha 通道，而是一次淡化全部内容。]],
		[ "$nocull" ] = [[绘制每个三角形的正反两面。当斗篷、裙子、叶片等单面表面从背面观看会消失时启用。这样会使该表面的绘制开销翻倍。]],
		[ "$vertexcolor" ] = [[允许模型中预先绘制的顶点颜色为材质着色。模型没有顶点颜色时不会产生效果。]],
		[ "$vertexalpha" ] = [[允许模型中预先绘制的顶点透明度淡化材质。模型没有这种数据时不会产生效果。]],
		[ "$bumpmap" ] = [[法线贴图用颜色存储表面形状，使光线看起来遇到凹凸、接缝和皱纹，而无需增加真实几何体。法线贴图通常呈浅蓝紫色；看起来像普通照片的图像并不是法线贴图，可用“生成”按钮从颜色纹理创建。还要注意两点：其 Alpha 通道默认充当 Phong 和反射遮罩；凹凸映射需要模型编译时包含切线数据，缺少切线的模型无论怎样设置都不会显示凹凸。]],
		[ "$bumpframe" ] = [[动画法线贴图的起始帧。普通单帧法线贴图会忽略此项。]],
		[ "$bumptransform" ] = [[独立于颜色纹理缩放、旋转和平移法线贴图，可用它让细小凹凸比表面颜色更密集地平铺。]],
		[ "$ssbump" ] = [[声明该法线贴图是自阴影凹凸贴图（SSBump）：它存储光照方向而不是表面角度，格式不同。只有纹理本来就是按此格式制作时才启用；对普通法线贴图启用会使光照异常。]],
		[ "$normalmapalphaenvmapmask" ] = [[使用法线贴图的 Alpha 通道决定反射出现的位置，而不是颜色纹理的 Alpha。这样颜色纹理的 Alpha 就可以留给透明度。]],
		[ "$phong" ] = [[启用 Source 为皮肤、皮革、乳胶和潮湿表面使用的柔和包裹式高光，通常是角色模型最明显的视觉提升。它需要 $bumpmap；没有法线贴图就完全无效。默认由法线贴图的 Alpha 通道控制高光位置：白色发亮，黑色无光。]],
		[ "$phongboost" ] = [[控制高光亮度。皮肤通常约为 1–2，抛光皮革或湿塑料约为 5–20；设得太高会让一切看起来像涂了油。]],
		[ "$phongexponent" ] = [[控制高光的集中程度。低值产生皮肤般宽而柔的光泽，高值产生抛光金属般小而锐利的亮点。可尝试：皮肤 5、塑料 20–40、金属 60 以上。这里任何大于 0 的值都会完全覆盖 $phongexponenttexture；若已生成指数贴图却看不到变化，请将此值设为 0，把控制权交还给纹理。]],
		[ "$phongexponenttexture" ] = [[让高光紧致度随表面区域变化，而不是整张材质只用一个数值，因此同一纹理表上的皮肤和皮带可以呈现不同光泽。各通道用途不同：红色控制紧致度，绿色控制高光吸收多少表面颜色，Alpha 用作边缘光遮罩。]],
		[ "$phongexponentfactor" ] = [[乘上指数纹理给出的值，无需重画即可让整个表面的高光更锐利或更柔和。注意两个陷阱：默认值 0 表示“未使用”，不是“平坦”；重现正常行为的值是 149 而不是 1。此外它来自 Team Fortress 2 和 Source 2013，在此处可能被完全忽略。]],
		[ "$phongalbedotint" ] = [[让高光带上下面表面的颜色而不是保持白色，例如红色表面会产生红色光泽。需要 $phongexponenttexture，其绿色通道控制着色量。]],
		[ "$phongalbedoboost" ] = [[增强由 $phongalbedotint 产生的彩色高光部分。]],
		[ "$phongtint" ] = [[直接设置高光颜色。[1 1 1] 为白色；暖色皮肤通常使用类似 [1 0.8 0.7] 的值更自然。]],
		[ "$phongfresnelranges" ] = [[控制高光随观察角度的变化；真实表面在斜视时通常比正视时更亮。三个数值依次对应正面、中间角度和边缘。[0 0.5 1] 是自然衰减，[1 1 1] 关闭角度变化并均匀发亮，[0 1 0] 会在中间形成明显亮带。]],
		[ "$phongwarptexture" ] = [[使用查找纹理在高光衰减过程中重新着色，适合虹彩和珍珠质表面。]],
		[ "$phongdisablehalflambert" ] = [[阻止 $halflambert 在柔化漫反射光的同时也柔化高光。半兰伯特材质的高光显得发白或模糊时启用。]],
		[ "$basemapalphaphongmask" ] = [[从颜色纹理的 Alpha 而不是法线贴图的 Alpha 读取 Phong 遮罩。当法线贴图 Alpha 已用于其他用途时很有用。]],
		[ "$basemapluminancephongmask" ] = [[理论上使用颜色纹理的亮度作为 Phong 遮罩：亮区发光，暗区不发光。但它在 Garry's Mod 中不起作用，修改不会产生效果；请改用 $basemapalphaphongmask，或通过法线贴图生成器把遮罩绘制到法线贴图的 Alpha 通道。]],
		[ "$invertphongmask" ] = [[尽管名字如此，它在 Garry's Mod 中并不会反转 Phong 遮罩。游戏自带着色器只在反射代码中读取此值，因此它实际反转的是 $envmap 遮罩，而且仅在设置了 $envmap 时生效。它可免费反转无法重画的反射遮罩，但对其名称所指的 Phong 遮罩没有作用。]],
		[ "$phongmaskcontrastbrightness" ] = [[在使用遮罩前进行调整：第一个数值是对比度，第二个是亮度。这是笔刷着色器参数，模型不会读取它，因此在模型上修改不会产生效果。]],
		[ "$rimlight" ] = [[在轮廓周围添加柔和光晕，仿佛光线绕过边缘，可让角色从背景中突出，常用于风格化模型。需要 $phong。亮度跟随环境光，因此暗角中较弱、户外较强。]],
		[ "$rimlightexponent" ] = [[控制边缘光带的宽窄。值越高越贴近轮廓，越低则向内部扩散；2–8 通常最实用。]],
		[ "$rimlightboost" ] = [[控制边缘光亮度。超过约 4 时角色会开始像着火一样——有时这正是想要的效果。]],
		[ "$rimmask" ] = [[使用 $phongexponenttexture 的 Alpha 通道限制边缘光，例如让皮肤发亮而布料不发亮。]],
		[ "$envmap" ] = [[让表面反射周围环境。设为 env_cubemap 时会采用地图作者放置的最近反射探针，这几乎总是正确选择。默认反射遍布整个表面；添加遮罩或启用 $normalmapalphaenvmapmask，可让应保持哑光的部分不反射。]],
		[ "$envmaptint" ] = [[按颜色通道控制反射强度。[1 1 1] 为全强度，[0.1 0.1 0.1] 只有轻微光泽。通常应先降低此项，因为全强度反射会像镀铬。]],
		[ "$envmapmask" ] = [[用灰度图决定反射位置：白色反射，黑色不反射。使用前请注意：引擎只会在既没有凹凸贴图也没有 $phong 的材质上读取此纹理。大多数玩家模型两者都有；在这种模型上，着色器会忽略此项并同时关闭 $envmap，因此添加遮罩反而会移除反射。此时遮罩必须放在法线贴图的 Alpha 通道中，法线贴图生成器可以写入。若未设置 $envmap，此项也完全无效。]],
		[ "$basealphaenvmapmask" ] = [[使用颜色纹理的 Alpha 作为反射遮罩。它不能与 $translucent 同时使用，因为两者都需要同一个通道。]],
		[ "$envmapcontrast" ] = [[加深反射。0 保持原样；1 会压暗亮点以外的部分，使表面看起来更坚硬、更光滑。]],
		[ "$envmapsaturation" ] = [[控制反射的色彩饱和度。0 为灰度，1 保留周围环境的完整颜色。]],
		[ "$envmapfresnel" ] = [[让反射向斜视角度集中，模拟真实表面：远处看地板像镜子，脚下则较暗。1 为完整效果。]],
		[ "$envmaplightscale" ] = [[在暗处降低反射，避免光滑表面在无光房间里自行发亮。0 关闭，1 让反射完全跟随光照。]],
		[ "$envmapanisotropy" ] = [[沿表面方向拉伸反射，模拟拉丝金属把高光拖成一条线。]],
		[ "$selfillum" ] = [[让材质的部分区域自行发光并忽略周围光照，适合屏幕、眼睛、符文和炽热金属。默认由 $basetexture 的 Alpha 决定位置：白色发光，黑色不发光。若该通道已用于透明度，请用 $selfillummask 指向单独图像。它不会照亮其他物体，只会提亮自身表面。]],
		[ "$selfillummask" ] = [[用独立图像指定发光区域，从而把颜色纹理的 Alpha 留给透明度。白色发光，黑色不发光。]],
		[ "$selfillumtint" ] = [[设置发光区域的颜色。大于 1 的值可将亮度推高到产生泛光。]],
		[ "$selfillumfresnel" ] = [[让发光随观察角度变化，表面转离视线时会增强。适合屏幕和眼睛。]],
		[ "$selfillumfresnelminmaxexp" ] = [[塑造上述角度衰减：三个数值分别控制最小亮度、最大亮度，以及两者之间过渡的锐利程度。]],
		[ "$detail" ] = [[在主纹理上更密集地平铺第二张纹理，以补充主纹理分辨率不足的近距离细节，例如毛孔、织物纹理和混凝土颗粒。它只在近处明显，这正是用途：成本很低，并能防止镜头靠近时表面显得平坦。]],
		[ "$detailscale" ] = [[控制细节纹理在主纹理上重复多少次。4 较柔和，20 以上产生细颗粒；过高会变成噪点。]],
		[ "$detailblendfactor" ] = [[控制细节的明显程度。建议从 0.2–0.5 的低值开始；细节应当让人感觉到，而不是一眼就看到。]],
		[ "$detailblendmode" ] = [[控制细节纹理与底色的组合方式。0 为相乘，会变暗；1 为相加，会变亮；7 为 mod2x，中灰保持表面不变，更亮或更暗的像素向相应方向调整。制作颗粒时通常应选择 7。]],
		[ "$detailtint" ] = [[在混合前为细节纹理着色。]],
		[ "$halflambert" ] = [[柔化光照衰减，让未受光的一侧仍可见而不会变黑。Half-Life 2 用它避免角色像半边陷在阴影中，尤其适合风格化和动漫模型。它几乎没有成本；角色对比度过强时值得尝试。]],
		[ "$lightwarptexture" ] = [[使用一像素高的渐变重新定义光照如何转为亮度。引擎不再平滑着色，而是从渐变左端（未受光）到右端（完全受光）查值。赛璐璐着色就是这样实现：两个平坦色带会产生硬边卡通光照，冷暖渐变则产生绘画感。]],
		[ "$notint" ] = [[忽略实体通过“颜色”工具或 Lua 设置的颜色，使此材质始终保留自身颜色。]],
		[ "$receiveflashlight" ] = [[允许手电筒和投射纹理照亮此材质，即使它是半透明的；否则这些光源会跳过它。]],
		[ "$nodecal" ] = [[防止弹孔、血迹和喷漆贴花附着在表面。Lua 对模型贴花的控制按整个物件而不是按子材质提供，因此在任一材质槽启用此项都会抑制整个物件的贴花。设置变化时已有贴花会被清除。]],
		[ "$basetexturetransform" ] = [[在不改动模型 UV 的情况下平移、缩放和旋转颜色纹理。Scale 大于 1 会增加平铺次数并让纹理变小，小于 1 则放大；Translate 用于滑动，1 代表完整移动一格；Centre 是缩放和旋转的轴心，通常应使用中点 0.5 0.5。]],
		[ "$detailtexturetransform" ] = [[平移、缩放和旋转细节纹理。请注意 $detailscale 已负责平铺，因此此项主要用于旋转颗粒、避免它与网格方向完全对齐。]],
		[ "$envmapmasktransform" ] = [[平移、缩放和旋转反射遮罩。]],
		[ "$ignorez" ] = [[让表面穿墙绘制，从地图任何位置都能看见。这是明显的 X 光效果，并不细微。]],
		[ "$wireframe" ] = [[只绘制三角形的边，可用于查看模型的网格结构。]],
		[ "$flat" ] = [[完全跳过光照，以全亮度绘制纹理。]],
		[ "$nofog" ] = [[使表面不受地图雾影响，在其他物体随距离淡去时仍保持清晰。]],
		[ "$nolod" ] = [[阻止引擎在远处换用较低分辨率的纹理版本。]],
		[ "$decal" ] = [[把材质视为贴花，用于覆盖在另一个表面上。]],
		[ "$reflectivity" ] = [[控制此表面向周围反弹多少光。它只在编译地图时使用，因此运行游戏时修改没有效果。]],
		[ "$iris" ] = [[眼睛的虹膜图像。在 EyeRefract 着色器中，它取代 $basetexture。]],
		[ "$eyeballradius" ] = [[控制眼球曲率。较大值让虹膜向外鼓起并增强折射，较小值则让它更平坦。]],
		[ "$dilation" ] = [[控制瞳孔大小。0.5 为中性，较低会收缩，较高会扩张。]],
		[ "$glossiness" ] = [[控制眼睛看起来有多湿，也就是角膜高光的强度。]],
		[ "$parallaxstrength" ] = [[控制头部转动时虹膜在角膜下方看起来移动多少；这种视差会让眼睛显得有深度。]],
		[ "$ambientocclcolor" ] = [[设置眼球与眼眶交界处的阴影颜色，避免眼睛看起来像贴在脸上的球。]],
		[ "$treesway" ] = [[让整个模型随风弯曲。1 会像树干一样绕根部摆动；2 会让每个顶点独立摆动，更适合草和树叶。]],
	},
	ja = {
		[ "$basetexture" ] = [[サーフェスの主な色画像です。形状ではなく塗装に相当し、ほかの効果はすべてこの上に重なります。パスは materials/ の内側から書き、拡張子を省きます。たとえば materials/models/kleiner/kleiner_sheet.vtf は models/kleiner/kleiner_sheet と入力します。アルファチャンネルは共有され、別の場所を指定しない限り、透明度、Phong マスク、反射マスクのすべてがこれを読みます。]],
		[ "$frame" ] = [[アニメーションテクスチャを開始するフレームです。.vtf に実際に複数フレームが入っている場合だけ働き、通常の1枚テクスチャでは無視されます。]],
		[ "$model" ] = [[マップ形状ではなくモデル用のマテリアルであることを示します。このエディターが作るものでは自動的に有効になり、無効にすると通常はサーフェスの描画が崩れます。]],
		[ "$surfaceprop" ] = [[物理材質を指定します。撃ったときの音とパーティクル、滑りやすさなどが変わります。metal、flesh、glass、wood、dirt などを試してください。ゲームプレイだけに関わる設定で、見た目は変わりません。]],
		[ "$color2" ] = [[マテリアル全体に色を付けます。[1 1 1] は変更なし、[1 0.5 0.5] は赤を保ち緑と青を半分にして赤みを付けます。1 を超える値は明るくします。モデルでは通常こちらを使います。ライティング後に適用されるため、影が影のまま残ります。]],
		[ "$color" ] = [[ライティング前に適用される古い色付けで、表面が白っぽくなりがちです。モデルでは $color2 の方が同じ役割をうまく果たすため、$color2 が効かない場合だけ使ってください。]],
		[ "$blendtintbybasealpha" ] = [[$color2 を、テクスチャのアルファが白い部分だけに制限します。チームカラーは、アルファチャンネルにマスクを描き、その領域だけを着色して作れます。アルファチャンネルを占有するため、アルファを使う透明表現とは併用できません。]],
		[ "$blendtintcoloroverbase" ] = [[マスク領域で色をどう混ぜるかを決めます。0 はテクスチャに色を乗算してディテールを残し、1 はテクスチャを単色で置き換えます。中間値では両者の間を補間します。]],
		[ "$desaturatewithbasealpha" ] = [[テクスチャ自身のアルファチャンネルを範囲として色を抜きます。0 はそのまま、1 はマスク部分をグレースケールにします。]],
		[ "$translucent" ] = [[$basetexture のアルファチャンネルでサーフェスを半透明にします。アルファが黒なら見えず、白なら不透明、灰色ならその中間です。注意点は描画順です。エンジンは半透明サーフェスをひとまとまりで描くため、同じモデルの半透明パーツ同士が逆順になり、裏返ったように見えることがあります。髪、葉、金網など硬い輪郭には $alphatest を使ってください。軽く、正しい順序で描画されます。]],
		[ "$alphatest" ] = [[$basetexture のアルファで各ピクセルを完全表示か完全非表示のどちらかにする、硬い輪郭の透明表現です。半透明はありません。髪、草木、格子、布の切り抜きにはほぼ常にこちらが適し、描画順が正しく $translucent より大幅に軽量です。]],
		[ "$alphatestreference" ] = [[$alphatest のしきい値です。アルファがこの値を超えたピクセルだけが残ります。低くすると多く残り、高くすると深く切り取られます。通常は 0.5 から始め、髪が欠けすぎるなら 0.3 付近まで下げ、縁に残像が出るなら上げます。]],
		[ "$allowalphatocoverage" ] = [[ゲームのアンチエイリアスで $alphatest の硬い縁を薄くして滑らかにします。プレイヤーが MSAA を有効にしている場合だけ効果があります。]],
		[ "$additive" ] = [[背景を覆う代わりに、背景へマテリアルの色を加算します。黒は完全に消え、明るい部分は発光します。炎、エネルギー、ホログラム、ガラスのハイライトに向きますが、固体に見せたいものには不向きです。]],
		[ "$alpha" ] = [[マテリアル全体を均等に薄くします。1 は不透明、0 は見えません。$translucent と違ってテクスチャのアルファを無視し、全体を一度に減衰させます。]],
		[ "$nocull" ] = [[すべての三角形を表裏とも描画します。マント、スカート、葉などの片面サーフェスが裏から見ると消える場合に有効にします。そのサーフェスの描画コストは2倍になります。]],
		[ "$vertexcolor" ] = [[モデルに塗り込まれた頂点カラーでマテリアルを着色できるようにします。モデル側に頂点カラーがなければ何も起こりません。]],
		[ "$vertexalpha" ] = [[モデルに塗り込まれた頂点アルファでマテリアルを薄くできるようにします。モデル側にそのデータがなければ何も起こりません。]],
		[ "$bumpmap" ] = [[法線マップは表面形状を色として保存し、実際のポリゴンを増やさずに凹凸、継ぎ目、しわがあるように光を反応させます。多くは淡い青紫色で、写真のような画像は法線マップではありません。「生成」ボタンでカラーテクスチャから作れます。注意点は2つあります。アルファチャンネルは既定で Phong と反射のマスクに使われます。またバンプマッピングにはモデルへコンパイルされた接線データが必要で、それがないモデルでは何を設定しても効果がありません。]],
		[ "$bumpframe" ] = [[アニメーション法線マップの開始フレームです。通常の1枚の法線マップでは無視されます。]],
		[ "$bumptransform" ] = [[カラーテクスチャとは別に法線マップを拡大縮小、回転、移動します。細かな凹凸を塗装より密にタイルするときに使います。]],
		[ "$ssbump" ] = [[法線マップがセルフシャドウ・バンプマップ（SSBump）であると指定します。これは表面角度ではなく光の方向を保存する別形式です。その形式で作られたテクスチャだけで有効にしてください。通常の法線マップで有効にするとライティングがおかしくなります。]],
		[ "$normalmapalphaenvmapmask" ] = [[カラーテクスチャのアルファではなく、法線マップのアルファで反射する場所を決めます。カラーテクスチャのアルファを透明度に使えるようになります。]],
		[ "$phong" ] = [[肌、革、ラテックス、濡れた表面に Source が使う、柔らかく回り込む光沢を有効にします。キャラクターモデルでは特に大きな見た目の改善になります。$bumpmap が必須で、ない場合はまったく働きません。既定では法線マップのアルファが光沢の位置を決め、白が光沢、黒がつや消しです。]],
		[ "$phongboost" ] = [[光沢の明るさです。肌は 1～2、磨いた革や濡れたプラスチックは 5～20 程度です。上げすぎると何もかも油を塗ったように見えます。]],
		[ "$phongexponent" ] = [[光沢の鋭さを決めます。低い値は肌のように広く柔らかく、高い値は磨いた金属のように小さく鋭い輝きになります。目安は肌 5、プラスチック 20～40、金属 60 以上です。ここが 0 より大きいと $phongexponenttexture を完全に上書きします。指数マップを作ったのに変化がない場合は 0 に戻し、テクスチャへ制御を返してください。]],
		[ "$phongexponenttexture" ] = [[光沢の鋭さを一つの数値ではなく場所ごとに変えます。同じテクスチャシートの肌と革ベルトを別の光沢にできます。各チャンネルの意味は、赤が鋭さ、緑がハイライトへ表面色を取り込む量、アルファがリムライトのマスクです。]],
		[ "$phongexponentfactor" ] = [[指数テクスチャの値を乗算し、塗り直さずに表面全体の光沢を鋭くまたは柔らかくします。注意点が2つあります。既定の 0 は「平坦」ではなく「未使用」を意味し、通常動作を再現する値は 1 ではなく 149 です。また Team Fortress 2 と Source 2013 由来のため、ここでは無視される場合があります。]],
		[ "$phongalbedotint" ] = [[ハイライトを白ではなく下地の色にします。赤い表面なら赤い光沢になります。$phongexponenttexture が必要で、その緑チャンネルが色の量を制御します。]],
		[ "$phongalbedoboost" ] = [[$phongalbedotint で色付けされたハイライト部分を強めます。]],
		[ "$phongtint" ] = [[ハイライトの色を直接指定します。[1 1 1] は白です。暖かい肌には [1 0.8 0.7] のような値が自然に見えることがあります。]],
		[ "$phongfresnelranges" ] = [[視線角度による光沢の変化を制御します。実物の表面は正面よりもかすめる角度で強く光ります。3つの数値は正面、中間、輪郭の順です。[0 0.5 1] は自然な減衰、[1 1 1] は角度効果を切って均一に光らせ、[0 1 0] は中間に強い帯を作ります。]],
		[ "$phongwarptexture" ] = [[ハイライトの減衰に沿って色を変えるルックアップ画像です。玉虫色や真珠調の仕上げに使います。]],
		[ "$phongdisablehalflambert" ] = [[$halflambert が拡散光だけでなく光沢まで柔らかくするのを止めます。ハーフランバート材質でハイライトが白っぽくぼやける場合に有効にします。]],
		[ "$basemapalphaphongmask" ] = [[法線マップのアルファではなく、カラーテクスチャのアルファから Phong マスクを取ります。法線マップのアルファを別用途に使っている場合に便利です。]],
		[ "$basemapluminancephongmask" ] = [[カラーテクスチャの明るさを Phong マスクとして使い、明部を光らせ暗部を光らせないための設定です。しかし Garry's Mod では動作せず、変更しても効果はありません。$basemapalphaphongmask を使うか、法線マップ生成器で法線マップのアルファにマスクを描いてください。]],
		[ "$invertphongmask" ] = [[名前に反して、Garry's Mod では Phong マスクを反転しません。付属シェーダーはこの値を反射コード内だけで読み取るため、実際に反転するのは $envmap マスクで、$envmap が設定されている場合だけです。塗り直せない反射マスクを手軽に逆転できますが、名前どおりの用途には使えません。]],
		[ "$phongmaskcontrastbrightness" ] = [[使用前のマスクを調整し、最初の数値がコントラスト、2番目が明るさです。ブラシ用シェーダーパラメーターなのでモデルでは読み取られず、変更しても効果がありません。]],
		[ "$rimlight" ] = [[輪郭の周りに光が回り込むような柔らかい輝きを加え、キャラクターを背景から浮かせます。スタイライズされたモデルでよく使われます。$phong が必要です。明るさは周囲光に従うため、暗い場所では弱く屋外では強くなります。]],
		[ "$rimlightexponent" ] = [[リムの帯の細さです。高いほど輪郭に密着し、低いほど内側へ広がります。実用的な範囲は 2～8 です。]],
		[ "$rimlightboost" ] = [[リムの明るさです。およそ 4 を超えるとキャラクターが燃えているように見え始めますが、それが狙いの場合もあります。]],
		[ "$rimmask" ] = [[$phongexponenttexture のアルファチャンネルでリムライトを制限します。たとえば布では消し、肌だけに出せます。]],
		[ "$envmap" ] = [[周囲の環境をサーフェスへ反射させます。env_cubemap にするとマップ作者が置いた最寄りの反射プローブを使い、ほとんどの場合はこれが正解です。既定では全面に反射します。マスクを追加するか $normalmapalphaenvmapmask を有効にして、つや消し部分から反射を除いてください。]],
		[ "$envmaptint" ] = [[色チャンネルごとの反射強度です。[1 1 1] は最大、[0.1 0.1 0.1] は薄い光沢です。最大反射はクロームのように見えるため、通常は最初にここを下げます。]],
		[ "$envmapmask" ] = [[反射する場所を決めるグレースケール画像です。白は反射し、黒は反射しません。重要な注意として、エンジンがこのテクスチャを読むのは、バンプマップも $phong もないマテリアルだけです。ほぼすべてのプレイヤーモデルには両方があり、その場合シェーダーはこの設定を無視し $envmap も切るため、マスクを加えると反射を整えるどころか消してしまいます。そのような材質ではマスクを法線マップのアルファに入れる必要があり、法線マップ生成器で作成できます。$envmap が未設定なら、これもまったく働きません。]],
		[ "$basealphaenvmapmask" ] = [[カラーテクスチャのアルファを反射マスクに使います。同じチャンネルを必要とするため $translucent とは併用できません。]],
		[ "$envmapcontrast" ] = [[反射を引き締めます。0 はそのまま、1 は明るい部分以外を暗くし、より硬く磨かれた表面に見せます。]],
		[ "$envmapsaturation" ] = [[反射の色鮮やかさです。0 はグレースケール、1 は周囲の色を完全に保ちます。]],
		[ "$envmapfresnel" ] = [[実際の表面のように、かすめる角度へ反射を寄せます。床は遠くを見ると鏡のようでも足元では鈍く見えます。1 で最大効果です。]],
		[ "$envmaplightscale" ] = [[暗所で反射を弱め、光のない部屋で光沢面が発光して見えるのを防ぎます。0 は無効、1 は反射を完全に照明へ連動させます。]],
		[ "$envmapanisotropy" ] = [[ブラッシュドメタルがハイライトを線状に伸ばすように、表面方向へ反射を引き伸ばします。]],
		[ "$selfillum" ] = [[周囲の照明を無視してマテリアルの一部を自発光させます。画面、目、ルーン、熱い金属などに向きます。既定では $basetexture のアルファが場所を決め、白が発光、黒が非発光です。そのチャンネルを透明度に使っているなら、$selfillummask で別画像を指定してください。ほかの物体は照らさず、この表面だけが明るくなります。]],
		[ "$selfillummask" ] = [[発光場所を指定する専用画像です。カラーテクスチャのアルファを透明度に空けられます。白が発光し、黒は発光しません。]],
		[ "$selfillumtint" ] = [[発光領域に色を付けます。1 を超える値にするとブルームが出るほど明るくできます。]],
		[ "$selfillumfresnel" ] = [[視線角度によって発光を変え、サーフェスがこちらから逸れるほど強くします。画面や目に適しています。]],
		[ "$selfillumfresnelminmaxexp" ] = [[その角度減衰を形作る3値で、最小発光、最大発光、その間の変化の鋭さを指定します。]],
		[ "$detail" ] = [[主テクスチャよりはるかに細かくタイルする2枚目のテクスチャです。毛穴、布目、コンクリートの粒など、主画像の解像度では足りない近接ディテールを加えます。近距離だけで目立つのが目的で、低コストのままカメラが近づいたときの平坦さを防ぎます。]],
		[ "$detailscale" ] = [[ディテールテクスチャを主テクスチャ上で何回繰り返すかを決めます。4 は穏やか、20 以上は細かな粒になります。高すぎるとノイズになります。]],
		[ "$detailblendfactor" ] = [[ディテールの強さです。まず 0.2～0.5 程度の低い値から始めてください。ディテールは目立たせるより、感じさせるものです。]],
		[ "$detailblendmode" ] = [[ディテールと下地色の合成方法です。0 は乗算で暗くなり、1 は加算で明るくなります。7 は mod2x で、中間灰色は表面を変えず、明暗のピクセルがそれぞれの方向へ押します。粒状ディテールには通常 7 が適します。]],
		[ "$detailtint" ] = [[合成する前にディテールテクスチャへ色を付けます。]],
		[ "$halflambert" ] = [[光の減衰を柔らかくし、光が当たらない側を黒くせず見える状態に保ちます。Half-Life 2 のキャラクターが半分影に沈んで見えない理由で、スタイライズやアニメ調モデルに特に向きます。コストはほぼなく、コントラストが強すぎるキャラクターで試す価値があります。]],
		[ "$lightwarptexture" ] = [[高さ1ピクセルのグラデーションで、光が明るさへ変わる仕組みを書き換えます。滑らかに陰影を付ける代わりに、エンジンは左（無照明）から右（完全照明）を参照します。2本の平坦な帯なら硬いセルルック、暖色から寒色のグラデーションなら絵画的な表現になります。]],
		[ "$notint" ] = [[Colour ツールや Lua がエンティティに設定した色を無視し、このマテリアル固有の色を保ちます。]],
		[ "$receiveflashlight" ] = [[通常は飛ばされる半透明状態でも、フラッシュライトと投影テクスチャがこのマテリアルを照らせるようにします。]],
		[ "$nodecal" ] = [[弾痕、血、スプレーのデカールがこの表面に付かなくなります。モデルのデカール描画は Lua へサブマテリアル単位ではなくプロップ単位で公開されているため、どれか1スロットで有効にするとプロップ全体のデカールが抑止されます。設定変更時に既存デカールも消去されます。]],
		[ "$basetexturetransform" ] = [[モデル自身の UV を変えずにカラーテクスチャを移動、拡大縮小、回転します。Scale が 1 より大きいとタイル回数が増えて小さくなり、1 未満では拡大します。Translate は移動で、1 が1タイル分です。Centre は拡大縮小と回転の中心で、ほとんどの場合は中央の 0.5 0.5 が適切です。]],
		[ "$detailtexturetransform" ] = [[ディテールテクスチャを移動、拡大縮小、回転します。タイル数はすでに $detailscale が扱うため、主に粒の向きをグリッドから外す用途です。]],
		[ "$envmapmasktransform" ] = [[反射マスクを移動、拡大縮小、回転します。]],
		[ "$ignorez" ] = [[壁を通してサーフェスを描画し、マップのどこからでも見えるようにします。控えめではない X 線効果です。]],
		[ "$wireframe" ] = [[三角形の辺だけを描画します。モデルの構造を見るのに便利です。]],
		[ "$flat" ] = [[ライティングを完全に省き、テクスチャを最大の明るさで描画します。]],
		[ "$nofog" ] = [[マップの霧をこのサーフェスに適用せず、ほかが距離で薄れる場所でも鮮明に保ちます。]],
		[ "$nolod" ] = [[遠距離でエンジンが低解像度版テクスチャへ切り替えるのを防ぎます。]],
		[ "$decal" ] = [[別のサーフェス上に重ねるデカールとしてマテリアルを扱います。]],
		[ "$reflectivity" ] = [[このサーフェスが周囲へ反射する光の量です。マップのコンパイル時だけ使われるため、実行中は効果がありません。]],
		[ "$iris" ] = [[目の虹彩画像です。EyeRefract シェーダーでは $basetexture の代わりに使われます。]],
		[ "$eyeballradius" ] = [[眼球の曲率です。大きい値は虹彩を外へ膨らませて屈折を強め、小さい値は平らにします。]],
		[ "$dilation" ] = [[瞳孔の大きさです。0.5 が中立で、低いと収縮し、高いと拡張します。]],
		[ "$glossiness" ] = [[目がどれだけ濡れて見えるか、つまり角膜ハイライトの強さです。]],
		[ "$parallaxstrength" ] = [[頭が回ったとき、虹彩が角膜の下でどれだけずれて見えるかを決めます。この視差が目に奥行きを与えます。]],
		[ "$ambientocclcolor" ] = [[眼球と眼窩が接する場所の陰影色です。目が顔に貼り付いた球のように見えるのを防ぎます。]],
		[ "$treesway" ] = [[モデル全体を風で曲げます。1 は木の幹のように根元を中心に揺れ、2 は各頂点を個別に揺らすため草や葉に向きます。]],
	},
	ko = {
		[ "$basetexture" ] = [[표면의 주 색상 이미지로, 모양이 아니라 표면에 칠한 색에 해당합니다. 다른 모든 효과는 이 위에 겹쳐집니다. 경로는 materials/ 폴더 안을 기준으로 쓰고 확장자는 생략합니다. 예를 들어 materials/models/kleiner/kleiner_sheet.vtf는 models/kleiner/kleiner_sheet로 입력합니다. 알파 채널은 공유되므로 별도 위치를 지정하지 않으면 투명도, Phong 마스크, 반사 마스크가 모두 이 채널을 읽습니다.]],
		[ "$frame" ] = [[애니메이션 텍스처를 시작할 프레임입니다. .vtf에 실제로 여러 프레임이 들어 있을 때만 작동하며 일반 단일 프레임 텍스처에서는 무시됩니다.]],
		[ "$model" ] = [[이 재질이 맵 지오메트리가 아니라 모델용임을 표시합니다. 편집기가 만드는 재질에는 자동으로 켜지며, 끄면 대개 표면이 잘못 렌더링됩니다.]],
		[ "$surfaceprop" ] = [[총에 맞을 때 나는 소리와 파티클, 표면의 미끄러움 같은 물리 재질을 지정합니다. metal, flesh, glass, wood, dirt 등을 사용해 보세요. 게임플레이만 바꾸며 외형에는 영향을 주지 않습니다.]],
		[ "$color2" ] = [[재질 전체에 색조를 입힙니다. [1 1 1]은 원본 그대로이고 [1 0.5 0.5]는 빨강을 유지한 채 초록과 파랑을 절반으로 줄여 붉게 만듭니다. 1보다 큰 값은 밝게 합니다. 조명 계산 뒤에 적용되어 그림자가 유지되므로 모델에는 보통 이것을 사용합니다.]],
		[ "$color" ] = [[조명 계산 전에 적용되는 오래된 색조 방식이라 표면이 씻겨 나간 듯 보일 수 있습니다. 모델에서는 $color2가 같은 작업을 더 잘하므로 $color2가 아무 효과도 없을 때만 사용하세요.]],
		[ "$blendtintbybasealpha" ] = [[텍스처 알파가 흰 부분에만 $color2를 적용합니다. 알파 채널에 마스크를 그려 해당 영역만 색칠하는 방식으로 팀 색상을 만들 수 있습니다. 알파 채널을 차지하므로 알파 기반 투명도와 함께 쓸 수 없습니다.]],
		[ "$blendtintcoloroverbase" ] = [[마스크 영역에서 색조가 원본과 섞이는 방식을 정합니다. 0은 텍스처에 색조를 곱해 디테일을 보존하고, 1은 텍스처를 단색으로 대체합니다. 중간 값은 두 방식 사이를 섞습니다.]],
		[ "$desaturatewithbasealpha" ] = [[텍스처 자체의 알파 채널로 영역을 정해 색을 뺍니다. 0은 그대로 두고 1은 마스크 영역을 회색조로 만듭니다.]],
		[ "$translucent" ] = [[$basetexture의 알파 채널로 표면을 반투명하게 만듭니다. 검은 알파는 보이지 않고 흰색은 불투명하며 회색은 그 중간입니다. 문제는 정렬입니다. 엔진은 각 반투명 표면을 통째로 그리므로 같은 모델의 반투명 부품 순서가 뒤바뀌어 안팎이 뒤집힌 듯 보일 수 있습니다. 머리카락, 잎, 철망처럼 가장자리가 뚜렷한 것은 더 가볍고 올바르게 정렬되는 $alphatest를 사용하세요.]],
		[ "$alphatest" ] = [[$basetexture의 알파 채널에 따라 각 픽셀을 완전히 표시하거나 완전히 없애는 딱딱한 가장자리 투명도입니다. 중간 투명도는 없습니다. 머리카락, 식물, 격자, 천의 구멍에는 거의 항상 이것이 적합하며, 정렬이 정확하고 $translucent보다 훨씬 가볍습니다.]],
		[ "$alphatestreference" ] = [[$alphatest의 임계값입니다. 알파가 이 값보다 높은 픽셀만 남습니다. 낮추면 텍스처가 더 많이 남고 높이면 더 많이 잘립니다. 보통 0.5에서 시작하세요. 머리카락이 뜯긴 듯하면 0.3 쪽으로 낮추고, 가장자리에 잔여 픽셀 테두리가 보이면 높이세요.]],
		[ "$allowalphatocoverage" ] = [[게임의 안티앨리어싱을 이용해 $alphatest의 딱딱한 가장자리를 부드럽게 합니다. 플레이어가 MSAA를 켰을 때만 효과가 있습니다.]],
		[ "$additive" ] = [[배경을 덮는 대신 재질 색을 배경에 더합니다. 검정은 완전히 사라지고 밝은 부분은 빛납니다. 불, 에너지, 홀로그램, 유리 하이라이트에 알맞고 단단해 보여야 하는 물체에는 맞지 않습니다.]],
		[ "$alpha" ] = [[재질 전체를 균일하게 흐리게 합니다. 1은 불투명, 0은 보이지 않습니다. $translucent와 달리 텍스처의 알파 채널을 무시하고 전체를 한꺼번에 줄입니다.]],
		[ "$nocull" ] = [[모든 삼각형의 앞뒤 면을 모두 그립니다. 망토, 치마, 잎처럼 한쪽 면만 있는 표면이 뒤에서 볼 때 사라지면 켜세요. 해당 표면의 렌더링 비용은 두 배가 됩니다.]],
		[ "$vertexcolor" ] = [[모델에 미리 칠해진 버텍스 색상이 재질 색조에 반영되게 합니다. 모델에 해당 데이터가 없으면 아무 효과도 없습니다.]],
		[ "$vertexalpha" ] = [[모델에 미리 칠해진 버텍스 투명도로 재질을 흐리게 합니다. 모델에 해당 데이터가 없으면 아무 효과도 없습니다.]],
		[ "$bumpmap" ] = [[노멀 맵은 표면 모양을 색으로 저장해 실제 지오메트리를 늘리지 않고도 빛이 돌기, 이음새, 주름을 만난 것처럼 보이게 합니다. 대개 연한 청보라색이며 사진처럼 보이는 이미지는 노멀 맵이 아닙니다. ‘생성’ 버튼으로 색상 텍스처에서 만들 수 있습니다. 두 가지를 알아 두세요. 알파 채널은 기본적으로 Phong과 반사 마스크로 쓰입니다. 또한 범프 매핑에는 모델을 컴파일할 때 포함된 탄젠트 데이터가 필요하므로, 그 데이터가 없는 모델에서는 어떤 값을 설정해도 효과가 없습니다.]],
		[ "$bumpframe" ] = [[애니메이션 노멀 맵의 시작 프레임입니다. 일반 단일 프레임 노멀 맵에서는 무시됩니다.]],
		[ "$bumptransform" ] = [[색상 텍스처와 별개로 노멀 맵을 확대·축소하고 회전하고 이동합니다. 미세한 요철을 표면 색보다 더 촘촘하게 반복할 때 사용합니다.]],
		[ "$ssbump" ] = [[노멀 맵이 표면 각도 대신 빛 방향을 저장하는 별도 형식인 셀프 섀도잉 범프 맵(SSBump)임을 지정합니다. 텍스처가 그 형식으로 제작된 경우에만 켜세요. 일반 노멀 맵에 켜면 조명이 이상해집니다.]],
		[ "$normalmapalphaenvmapmask" ] = [[색상 텍스처 알파 대신 노멀 맵 알파 채널로 반사가 나타날 위치를 정합니다. 색상 텍스처의 알파를 투명도에 사용할 수 있게 됩니다.]],
		[ "$phong" ] = [[Source가 피부, 가죽, 라텍스, 젖은 표면에 사용하는 부드럽게 감싸는 광택을 켭니다. 캐릭터 모델에서 가장 눈에 띄는 시각적 개선 중 하나입니다. $bumpmap이 반드시 필요하며 없으면 전혀 작동하지 않습니다. 기본적으로 노멀 맵의 알파가 광택 위치를 정해 흰색은 빛나고 검정은 무광입니다.]],
		[ "$phongboost" ] = [[광택 밝기입니다. 피부는 약 1~2, 광택 가죽이나 젖은 플라스틱은 약 5~20이 적당합니다. 지나치게 올리면 모든 것이 기름칠한 것처럼 보입니다.]],
		[ "$phongexponent" ] = [[광택이 얼마나 조밀한지 정합니다. 낮은 값은 피부처럼 넓고 부드러운 광택, 높은 값은 광택 금속처럼 작고 날카로운 반짝임을 만듭니다. 피부는 5, 플라스틱은 20~40, 금속은 60 이상을 시도해 보세요. 여기의 값이 0보다 크면 $phongexponenttexture를 완전히 덮어씁니다. 지수 맵을 만들었는데 변화가 없다면 값을 0으로 바꿔 텍스처에 제어권을 돌려주세요.]],
		[ "$phongexponenttexture" ] = [[광택 조밀도를 한 숫자로 고정하지 않고 표면 위치마다 다르게 합니다. 한 텍스처 시트의 피부와 가죽 벨트가 서로 다른 광택을 낼 수 있습니다. 채널별 의미는 빨강이 조밀도, 초록이 하이라이트에 표면색이 섞이는 양, 알파가 림 라이트 마스크입니다.]],
		[ "$phongexponentfactor" ] = [[지수 텍스처 값에 곱해 다시 그리지 않고도 전체 표면의 광택을 더 날카롭거나 부드럽게 합니다. 두 가지 함정이 있습니다. 기본값 0은 ‘평평함’이 아니라 ‘사용 안 함’이고, 정상 동작을 재현하는 값은 1이 아니라 149입니다. 또한 Team Fortress 2와 Source 2013의 기능이라 여기서는 무시될 수 있습니다.]],
		[ "$phongalbedotint" ] = [[하이라이트를 흰색이 아니라 아래 표면의 색으로 만듭니다. 빨간 표면에는 붉은 광택이 생깁니다. $phongexponenttexture가 필요하며 초록 채널이 색이 섞이는 양을 조절합니다.]],
		[ "$phongalbedoboost" ] = [[$phongalbedotint로 색이 입혀진 하이라이트 부분을 강화합니다.]],
		[ "$phongtint" ] = [[하이라이트 색을 직접 지정합니다. [1 1 1]은 흰색입니다. 따뜻한 피부는 [1 0.8 0.7] 같은 값이 더 자연스러울 수 있습니다.]],
		[ "$phongfresnelranges" ] = [[보는 각도에 따라 광택이 어떻게 달라지는지 조절합니다. 실제 표면은 정면보다 비스듬히 볼 때 더 빛납니다. 세 숫자는 정면, 중간 각도, 가장자리 순서입니다. [0 0.5 1]은 자연스러운 변화, [1 1 1]은 각도 효과를 끄고 균일하게 빛나며 [0 1 0]은 중간에 강한 띠를 만듭니다.]],
		[ "$phongwarptexture" ] = [[하이라이트가 약해지는 구간의 색을 다시 정하는 조회 이미지로, 무지갯빛이나 진주광택 마감에 사용합니다.]],
		[ "$phongdisablehalflambert" ] = [[$halflambert가 확산광과 함께 광택까지 부드럽게 만드는 것을 막습니다. 하프 램버트 재질의 하이라이트가 뿌옇게 보일 때 켜세요.]],
		[ "$basemapalphaphongmask" ] = [[노멀 맵 알파 대신 색상 텍스처 알파에서 Phong 마스크를 가져옵니다. 노멀 맵 알파가 이미 다른 용도로 쓰일 때 유용합니다.]],
		[ "$basemapluminancephongmask" ] = [[색상 텍스처 밝기를 Phong 마스크로 사용해 밝은 곳은 빛나고 어두운 곳은 빛나지 않게 하려는 설정입니다. 하지만 Garry's Mod에서는 작동하지 않아 값을 바꿔도 효과가 없습니다. $basemapalphaphongmask를 쓰거나 노멀 맵 생성기로 노멀 맵 알파 채널에 마스크를 그리세요.]],
		[ "$invertphongmask" ] = [[이름과 달리 Garry's Mod에서는 Phong 마스크를 반전하지 않습니다. 기본 셰이더가 이 값을 반사 코드에서만 읽으므로 실제로 뒤집는 것은 $envmap 마스크이며, $envmap이 설정된 경우에만 작동합니다. 다시 그릴 수 없는 반사 마스크를 손쉽게 뒤집을 수 있지만 이름대로의 용도에는 쓸 수 없습니다.]],
		[ "$phongmaskcontrastbrightness" ] = [[마스크를 사용하기 전에 조정합니다. 첫 번째 숫자는 대비, 두 번째는 밝기입니다. 브러시 셰이더 매개변수라 모델에서는 읽지 않으므로 값을 바꿔도 아무 효과가 없습니다.]],
		[ "$rimlight" ] = [[빛이 가장자리를 돌아 들어오는 것처럼 윤곽 둘레에 부드러운 빛을 더해 캐릭터를 배경에서 분리합니다. 스타일화된 모델에 흔히 사용됩니다. $phong이 필요합니다. 밝기는 주변광을 따르므로 어두운 구석에서는 약하고 야외에서는 강합니다.]],
		[ "$rimlightexponent" ] = [[림 라이트 띠의 폭을 정합니다. 값이 높으면 윤곽에 더 밀착하고 낮으면 안쪽으로 넓게 퍼집니다. 유용한 범위는 2~8입니다.]],
		[ "$rimlightboost" ] = [[림 라이트 밝기입니다. 약 4를 넘으면 캐릭터가 불붙은 것처럼 보이기 시작하지만, 그것이 의도일 수도 있습니다.]],
		[ "$rimmask" ] = [[$phongexponenttexture의 알파 채널로 림 라이트를 제한해 천에서는 끄고 피부에만 남길 수 있습니다.]],
		[ "$envmap" ] = [[표면이 주변 환경을 반사하게 합니다. env_cubemap으로 설정하면 맵 제작자가 배치한 가장 가까운 반사 프로브를 사용하며 거의 항상 이 선택이 적합합니다. 기본적으로 전체 표면이 반사합니다. 마스크를 추가하거나 $normalmapalphaenvmapmask를 켜 무광이어야 할 부분에서 반사를 제거하세요.]],
		[ "$envmaptint" ] = [[색상 채널별 반사 강도입니다. [1 1 1]은 최대 강도이고 [0.1 0.1 0.1]은 희미한 광택입니다. 최대 반사는 크롬처럼 보이므로 보통 가장 먼저 이 값을 낮춥니다.]],
		[ "$envmapmask" ] = [[반사 위치를 정하는 회색조 이미지입니다. 흰색은 반사하고 검정은 반사하지 않습니다. 사용 전 중요한 점이 있습니다. 엔진은 범프 맵도 $phong도 없는 재질에서만 이 텍스처를 읽습니다. 거의 모든 플레이어 모델은 둘 다 가지고 있어, 그런 모델에서는 셰이더가 이 설정을 무시하고 $envmap도 꺼 버립니다. 즉 마스크를 추가하면 반사를 다듬는 대신 없애게 됩니다. 이런 재질의 마스크는 노멀 맵 알파에 들어가야 하며 노멀 맵 생성기로 만들 수 있습니다. $envmap이 설정되지 않았다면 이것도 전혀 작동하지 않습니다.]],
		[ "$basealphaenvmapmask" ] = [[색상 텍스처의 알파를 반사 마스크로 사용합니다. 같은 채널이 필요한 $translucent와는 함께 쓸 수 없습니다.]],
		[ "$envmapcontrast" ] = [[반사를 더 깊게 만듭니다. 0은 그대로 두고 1은 밝은 부분을 제외한 나머지를 어둡게 해 표면을 더 단단하고 매끈하게 보이게 합니다.]],
		[ "$envmapsaturation" ] = [[반사의 색상 정도입니다. 0은 회색조, 1은 주변 환경의 색을 그대로 유지합니다.]],
		[ "$envmapfresnel" ] = [[실제 표면처럼 비스듬한 각도 쪽으로 반사가 강해지게 합니다. 바닥은 멀리 볼 때 거울 같고 발밑에서는 흐리게 보입니다. 1이 최대 효과입니다.]],
		[ "$envmaplightscale" ] = [[어두운 곳에서 반사를 줄여 조명이 없는 방에서 광택 표면이 스스로 빛나는 현상을 막습니다. 0은 끄기, 1은 반사를 조명에 완전히 연동합니다.]],
		[ "$envmapanisotropy" ] = [[브러시드 메탈이 하이라이트를 선으로 늘이는 것처럼 반사를 표면 방향으로 길게 늘입니다.]],
		[ "$selfillum" ] = [[주변 조명을 무시하고 재질 일부가 스스로 빛나게 합니다. 화면, 눈, 룬, 뜨거운 금속에 알맞습니다. 기본적으로 $basetexture의 알파가 위치를 정해 흰색은 빛나고 검정은 빛나지 않습니다. 해당 채널이 투명도에 쓰인다면 $selfillummask로 별도 이미지를 지정하세요. 다른 물체를 밝히지는 않고 이 표면만 밝아집니다.]],
		[ "$selfillummask" ] = [[빛나는 위치를 지정하는 전용 이미지로, 색상 텍스처의 알파를 투명도에 남겨 둡니다. 흰색은 빛나고 검정은 빛나지 않습니다.]],
		[ "$selfillumtint" ] = [[발광 영역의 색을 지정합니다. 1보다 큰 값은 블룸이 생길 만큼 밝게 만들 수 있습니다.]],
		[ "$selfillumfresnel" ] = [[보는 각도에 따라 발광을 바꿔 표면이 시선에서 돌아설수록 강하게 번쩍이게 합니다. 화면과 눈에 적합합니다.]],
		[ "$selfillumfresnelminmaxexp" ] = [[각도에 따른 발광 변화를 만드는 세 값으로, 최소 발광, 최대 발광, 그 사이 변화의 날카로움을 지정합니다.]],
		[ "$detail" ] = [[주 텍스처보다 훨씬 촘촘하게 반복되는 두 번째 텍스처로, 주 이미지의 해상도로 표현하기 어려운 모공, 직물 짜임, 콘크리트 알갱이 같은 근접 디테일을 더합니다. 가까이서만 보이는 것이 목적이며 비용이 낮고 카메라가 접근했을 때 표면이 밋밋해지는 것을 막습니다.]],
		[ "$detailscale" ] = [[디테일 텍스처가 주 텍스처 위에서 반복되는 횟수입니다. 4는 은은하고 20 이상은 미세한 입자를 만듭니다. 너무 높으면 노이즈가 됩니다.]],
		[ "$detailblendfactor" ] = [[디테일이 보이는 강도입니다. 0.2~0.5 정도의 낮은 값부터 시작하세요. 디테일은 눈에 띄기보다 느껴져야 합니다.]],
		[ "$detailblendmode" ] = [[디테일 텍스처와 아래 색상이 합쳐지는 방식입니다. 0은 곱셈으로 어두워지고, 1은 덧셈으로 밝아집니다. 7은 mod2x로 중간 회색은 표면을 바꾸지 않고 더 밝거나 어두운 픽셀이 양쪽으로 조절합니다. 입자 표현에는 보통 7이 적합합니다.]],
		[ "$detailtint" ] = [[혼합하기 전에 디테일 텍스처에 색조를 입힙니다.]],
		[ "$halflambert" ] = [[빛의 감쇠를 부드럽게 해 빛을 받지 않는 면도 검게 사라지지 않고 보이게 합니다. Half-Life 2 캐릭터가 절반쯤 그림자에 잠겨 보이지 않는 이유이며 스타일화·애니풍 모델에 특히 잘 맞습니다. 비용이 거의 없으므로 대비가 너무 강한 캐릭터에 시도해 보세요.]],
		[ "$lightwarptexture" ] = [[높이가 1픽셀인 그라데이션으로 빛이 밝기로 바뀌는 방식을 다시 정의합니다. 엔진은 부드럽게 음영을 계산하는 대신 왼쪽(빛 없음)에서 오른쪽(완전한 빛)까지 그라데이션을 조회합니다. 평평한 두 구간은 딱딱한 셀 셰이딩을 만들고 따뜻한 색에서 차가운 색으로 가는 그라데이션은 회화적인 느낌을 만듭니다.]],
		[ "$notint" ] = [[색상 도구나 Lua가 엔티티에 지정한 색을 무시해 이 재질이 항상 자체 색상을 유지하게 합니다.]],
		[ "$receiveflashlight" ] = [[반투명일 때도 손전등과 프로젝티드 텍스처가 이 재질을 비추게 합니다. 그렇지 않으면 이런 광원은 반투명 재질을 건너뜁니다.]],
		[ "$nodecal" ] = [[총알 자국, 피, 스프레이 데칼이 이 표면에 붙지 않게 합니다. 모델 데칼 렌더링은 Lua에 하위 재질별이 아니라 프롭별로 노출되므로 어느 슬롯에서든 켜면 프롭 전체의 데칼이 억제됩니다. 설정이 바뀔 때 기존 데칼도 지워집니다.]],
		[ "$basetexturetransform" ] = [[모델의 UV를 건드리지 않고 색상 텍스처를 이동·확대·축소·회전합니다. Scale이 1보다 크면 더 많이 반복되어 텍스처가 작아지고, 1보다 작으면 확대됩니다. Translate는 이동이며 1은 한 타일 전체 거리입니다. Centre는 크기 조절과 회전의 중심으로 보통 가운데인 0.5 0.5가 맞습니다.]],
		[ "$detailtexturetransform" ] = [[디테일 텍스처를 이동·확대·축소·회전합니다. 반복 횟수는 이미 $detailscale이 담당하므로 주로 입자 방향을 격자에서 비트는 데 사용합니다.]],
		[ "$envmapmasktransform" ] = [[반사 마스크를 이동·확대·축소·회전합니다.]],
		[ "$ignorez" ] = [[벽을 뚫고 표면을 그려 맵 어디서나 보이게 합니다. 은은한 효과가 아닌 엑스레이 효과입니다.]],
		[ "$wireframe" ] = [[삼각형의 가장자리만 그립니다. 모델이 어떻게 구성되었는지 확인할 때 유용합니다.]],
		[ "$flat" ] = [[조명을 완전히 건너뛰고 텍스처를 최대 밝기로 그립니다.]],
		[ "$nofog" ] = [[이 표면에 맵의 안개를 적용하지 않아 다른 물체가 거리 때문에 흐려질 때도 선명하게 보이게 합니다.]],
		[ "$nolod" ] = [[멀리서 엔진이 더 낮은 해상도의 텍스처 버전으로 바꾸는 것을 막습니다.]],
		[ "$decal" ] = [[다른 표면 위에 겹쳐 놓는 데칼로 재질을 취급합니다.]],
		[ "$reflectivity" ] = [[이 표면이 주변으로 되튕기는 빛의 양입니다. 맵을 컴파일할 때만 사용되므로 실행 중에는 아무 효과가 없습니다.]],
		[ "$iris" ] = [[눈의 홍채 이미지입니다. EyeRefract 셰이더에서는 $basetexture 대신 사용됩니다.]],
		[ "$eyeballradius" ] = [[안구의 곡률입니다. 큰 값은 홍채를 바깥으로 볼록하게 해 굴절을 강화하고 작은 값은 평평하게 합니다.]],
		[ "$dilation" ] = [[동공 크기입니다. 0.5가 중립이며 낮으면 수축하고 높으면 확장합니다.]],
		[ "$glossiness" ] = [[눈이 얼마나 젖어 보이는지, 즉 각막 하이라이트의 강도입니다.]],
		[ "$parallaxstrength" ] = [[머리가 돌아갈 때 홍채가 각막 아래에서 얼마나 움직이는 것처럼 보이는지 정합니다. 이 시차가 눈에 깊이감을 줍니다.]],
		[ "$ambientocclcolor" ] = [[안구와 눈구멍이 만나는 곳의 음영 색상으로, 눈이 얼굴에 붙인 공처럼 보이는 것을 막습니다.]],
		[ "$treesway" ] = [[모델 전체를 바람에 휘게 합니다. 1은 나무줄기처럼 밑동을 중심으로 흔들고, 2는 각 버텍스를 따로 흔들어 풀과 잎에 적합합니다.]],
	},
	fr = {
		[ "$basetexture" ] = [[L’image couleur principale de la surface : sa peinture, et non sa forme. Tous les autres effets se superposent à elle. Les chemins partent de l’intérieur de materials/ et omettent l’extension ; materials/models/kleiner/kleiner_sheet.vtf s’écrit donc models/kleiner/kleiner_sheet. Son canal alpha est partagé : sauf indication contraire, la transparence, le masque Phong et le masque de réflexion le lisent tous.]],
		[ "$frame" ] = [[Définit l’image de départ d’une texture animée. Ce réglage n’agit que si le fichier .vtf contient réellement plusieurs images ; il est ignoré sur une texture ordinaire.]],
		[ "$model" ] = [[Indique que le matériau appartient à un modèle et non à la géométrie de la carte. L’éditeur l’active automatiquement sur tout ce qu’il crée ; le désactiver produit généralement un mauvais rendu de la surface.]],
		[ "$surfaceprop" ] = [[Définit le matériau physique : son à l’impact, particules émises et adhérence de la surface. Essayez metal, flesh, glass, wood ou dirt. C’est uniquement une propriété de jouabilité : elle ne change rien visuellement.]],
		[ "$color2" ] = [[Teinte tout le matériau. [1 1 1] ne le modifie pas ; [1 0.5 0.5] conserve le rouge et divise le vert et le bleu par deux, ce qui donne une teinte rouge. Les valeurs supérieures à 1 éclaircissent. C’est la teinte à privilégier sur les modèles : appliquée après l’éclairage, elle préserve les ombres.]],
		[ "$color" ] = [[Ancienne teinte appliquée avant l’éclairage, qui tend à délaver la surface. Sur les modèles, $color2 remplit mieux le même rôle ; n’utilisez celle-ci que si $color2 ne produit aucun effet.]],
		[ "$blendtintbybasealpha" ] = [[Limite $color2 aux zones où l’alpha de la texture est blanc. C’est le principe des couleurs d’équipe : peignez un masque dans le canal alpha et seule cette zone sera teintée. Ce réglage monopolise le canal alpha et ne peut donc pas être combiné à une transparence fondée sur l’alpha.]],
		[ "$blendtintcoloroverbase" ] = [[Détermine le mélange de la teinte dans la zone masquée. 0 multiplie la teinte par la texture et conserve ses détails ; 1 remplace la texture par une couleur unie. Les valeurs intermédiaires fondent l’un dans l’autre.]],
		[ "$desaturatewithbasealpha" ] = [[Retire la couleur de la texture en utilisant son propre canal alpha pour choisir les zones. 0 ne change rien ; 1 passe la zone masquée en niveaux de gris.]],
		[ "$translucent" ] = [[Rend la surface translucide grâce au canal alpha de $basetexture : un alpha noir est invisible, blanc est opaque et gris est partiellement transparent. Attention au tri : le moteur dessine chaque surface translucide en bloc, si bien que deux parties translucides d’un même modèle peuvent être affichées dans le mauvais ordre et sembler retournées. Pour les cheveux, feuilles, grillages et autres bords nets, utilisez plutôt $alphatest : moins coûteux, il est trié correctement.]],
		[ "$alphatest" ] = [[Transparence à bord net : chaque pixel est soit entièrement visible, soit entièrement absent, selon le canal alpha de $basetexture. Il n’y a aucune semi-transparence. C’est presque toujours le bon choix pour les cheveux, feuillages, grilles et découpes de tissu : le tri est correct et le coût bien inférieur à $translucent.]],
		[ "$alphatestreference" ] = [[Seuil de $alphatest. Un pixel est conservé si son alpha dépasse cette valeur. Une valeur plus basse conserve davantage de texture ; une valeur plus haute la découpe davantage. Commencez à 0.5. Si les cheveux paraissent rongés, descendez vers 0.3 ; si un halo de pixels subsiste, augmentez la valeur.]],
		[ "$allowalphatocoverage" ] = [[Adoucit le bord dur laissé par $alphatest en utilisant l’anticrénelage du jeu. Ce réglage n’agit que si le joueur a activé le MSAA.]],
		[ "$additive" ] = [[Ajoute le matériau à ce qui se trouve derrière au lieu de le recouvrir. Le noir devient entièrement invisible et les zones claires brillent. Convient au feu, à l’énergie, aux hologrammes et aux reflets du verre, mais pas aux objets qui doivent paraître solides.]],
		[ "$alpha" ] = [[Estompe uniformément tout le matériau. 1 est opaque, 0 est invisible. Contrairement à $translucent, ce réglage ignore le canal alpha de la texture et atténue tout à la fois.]],
		[ "$nocull" ] = [[Dessine les deux côtés de chaque triangle. Activez-le lorsqu’une surface simple face — cape, jupe ou feuille — disparaît vue de dos. Le coût de dessin de cette surface est alors doublé.]],
		[ "$vertexcolor" ] = [[Permet aux couleurs de sommets peintes dans le modèle de teinter le matériau. Sans ces données dans le modèle, ce réglage ne fait rien.]],
		[ "$vertexalpha" ] = [[Permet à la transparence peinte dans les sommets du modèle d’estomper le matériau. Sans ces données dans le modèle, ce réglage ne fait rien.]],
		[ "$bumpmap" ] = [[Une normal map enregistre la forme de la surface sous forme de couleurs. Elle fait réagir la lumière comme s’il existait des bosses, coutures et plis, sans ajouter de géométrie réelle. Une normal map est généralement bleu-lilas pâle ; une image ressemblant à une photo n’en est pas une. Le bouton Générer peut en créer une depuis une texture couleur. Deux points importants : son canal alpha sert par défaut de masque Phong et de réflexion ; et le relief exige des tangentes compilées dans le modèle. Sur un modèle qui en est dépourvu, ajouter une normal map ne produit aucun effet, quels que soient les réglages.]],
		[ "$bumpframe" ] = [[Image de départ d’une normal map animée. Ce réglage est ignoré sur une normal map ordinaire.]],
		[ "$bumptransform" ] = [[Déplace, redimensionne et fait pivoter la normal map indépendamment de la texture couleur. Utilisez-le pour répéter un relief fin plus densément que la peinture.]],
		[ "$ssbump" ] = [[Indique que la normal map est une carte de relief auto-ombrée (SSBump), un format distinct qui stocke des directions de lumière plutôt que des angles de surface. Ne l’activez que si la texture a été créée ainsi ; sur une normal map ordinaire, l’éclairage devient anormal.]],
		[ "$normalmapalphaenvmapmask" ] = [[Utilise le canal alpha de la normal map, plutôt que celui de la texture couleur, pour décider où afficher les réflexions. Le canal alpha de la couleur reste ainsi disponible pour la transparence.]],
		[ "$phong" ] = [[Active le reflet doux et enveloppant que Source utilise pour la peau, le cuir, le latex et les surfaces mouillées. C’est l’une des améliorations visuelles les plus marquées pour un personnage. Il exige un $bumpmap et ne fait absolument rien sans lui. Par défaut, le canal alpha de la normal map place le reflet : blanc est brillant, noir est mat.]],
		[ "$phongboost" ] = [[Règle la luminosité du reflet. La peau se situe vers 1 à 2, le cuir poli ou le plastique mouillé vers 5 à 20. Une valeur excessive donne à tout un aspect huilé.]],
		[ "$phongexponent" ] = [[Règle la concentration du reflet. Les petites valeurs donnent un éclat large et doux comme la peau ; les grandes donnent un point petit et net comme le métal poli. Essayez 5 pour la peau, 20 à 40 pour le plastique, 60 et plus pour le métal. Toute valeur supérieure à 0 remplace entièrement $phongexponenttexture. Si votre map d’exposant semble inactive, remettez cette valeur à 0 pour rendre le contrôle à la texture.]],
		[ "$phongexponenttexture" ] = [[Fait varier la concentration du reflet selon les zones plutôt que d’imposer une valeur unique. La peau et une ceinture en cuir peuvent ainsi briller différemment sur la même planche de texture. Chaque canal a un rôle : le rouge règle la concentration, le vert la quantité de couleur de surface reprise par le reflet, et l’alpha masque l’éclairage de contour.]],
		[ "$phongexponentfactor" ] = [[Multiplie les valeurs de la texture d’exposant afin de rendre toute la surface plus nette ou plus douce sans la repeindre. Deux pièges : la valeur par défaut 0 signifie « inutilisé », pas « plat », et la valeur qui reproduit le comportement normal est 149, non 1. Ce paramètre vient aussi de Team Fortress 2 et Source 2013, et peut donc être simplement ignoré ici.]],
		[ "$phongalbedotint" ] = [[Donne au reflet la couleur de la surface sous-jacente au lieu de le laisser blanc : une surface rouge reçoit un éclat rouge. Nécessite $phongexponenttexture, dont le canal vert règle la quantité de couleur.]],
		[ "$phongalbedoboost" ] = [[Renforce la partie colorée du reflet produite par $phongalbedotint.]],
		[ "$phongtint" ] = [[Colore directement le reflet. [1 1 1] est blanc. Une peau chaude paraît souvent plus naturelle avec une valeur comme [1 0.8 0.7].]],
		[ "$phongfresnelranges" ] = [[Contrôle la variation du reflet selon l’angle de vue : les surfaces réelles brillent davantage en vue rasante que de face. Les trois nombres correspondent à la vue de face, l’angle moyen et le bord. [0 0.5 1] donne une progression naturelle ; [1 1 1] désactive l’effet angulaire et brille uniformément ; [0 1 0] forme une bande forte au milieu.]],
		[ "$phongwarptexture" ] = [[Image de référence qui recolore le reflet pendant son atténuation, utilisée pour les finitions irisées et nacrées.]],
		[ "$phongdisablehalflambert" ] = [[Empêche $halflambert d’adoucir le reflet en même temps que la lumière diffuse. Activez-le si le reflet paraît délavé sur un matériau en half-lambert.]],
		[ "$basemapalphaphongmask" ] = [[Prend le masque Phong dans l’alpha de la texture couleur plutôt que dans celui de la normal map. Utile lorsque l’alpha de la normal map remplit déjà un autre rôle.]],
		[ "$basemapluminancephongmask" ] = [[Est censé utiliser la luminosité de la texture couleur comme masque Phong : les zones claires brillent, les zones sombres non. Cela ne fonctionne pas dans Garry's Mod ; modifier ce paramètre ne produit aucun effet. Utilisez $basemapalphaphongmask ou peignez un masque dans l’alpha de la normal map avec le générateur.]],
		[ "$invertphongmask" ] = [[Malgré son nom, ce paramètre n’inverse PAS le masque Phong dans Garry's Mod. Le shader fourni ne le lit que dans le code des réflexions : il inverse donc réellement le masque de $envmap, et seulement si $envmap est défini. Il permet d’inverser gratuitement un masque de réflexion impossible à repeindre, mais ne remplit pas la fonction annoncée par son nom.]],
		[ "$phongmaskcontrastbrightness" ] = [[Ajuste le masque avant utilisation : le premier nombre est le contraste, le second la luminosité. C’est un paramètre de shader pour les surfaces de carte ; un modèle ne le lit pas, donc le modifier ici ne produit aucun effet.]],
		[ "$rimlight" ] = [[Ajoute une lueur douce autour de la silhouette, comme si la lumière contournait les bords. Elle détache un personnage du fond et est courante sur les modèles stylisés. Nécessite $phong. Sa luminosité suit la lumière ambiante : discrète dans un coin sombre, forte à l’extérieur.]],
		[ "$rimlightexponent" ] = [[Règle l’étroitesse de la bande lumineuse. Une valeur élevée la serre contre le contour ; une valeur basse l’étend vers l’intérieur. La plage utile est de 2 à 8.]],
		[ "$rimlightboost" ] = [[Règle la luminosité du contour. Au-delà d’environ 4, le personnage commence à sembler en feu — ce qui peut être l’effet recherché.]],
		[ "$rimmask" ] = [[Limite l’éclairage de contour avec le canal alpha de $phongexponenttexture, par exemple pour l’exclure du tissu et le conserver sur la peau.]],
		[ "$envmap" ] = [[Fait réfléchir l’environnement par la surface. Avec env_cubemap, elle utilise la sonde de réflexion la plus proche placée par l’auteur de la carte, ce qui est presque toujours souhaitable. Par défaut, la réflexion couvre toute la surface. Ajoutez un masque ou activez $normalmapalphaenvmapmask pour l’exclure des parties qui doivent rester mates.]],
		[ "$envmaptint" ] = [[Règle la force de la réflexion par canal de couleur. [1 1 1] est la pleine intensité ; [0.1 0.1 0.1] donne un léger éclat. C’est généralement le premier réglage à réduire, car une réflexion maximale ressemble à du chrome.]],
		[ "$envmapmask" ] = [[Image en niveaux de gris qui choisit où apparaît la réflexion : le blanc réfléchit, le noir non. Point essentiel : le moteur ne lit cette texture que sur un matériau SANS normal map et SANS $phong. Presque tous les modèles de joueur ont les deux ; leur shader ignore alors ce masque et désactive aussi $envmap, si bien qu’ajouter un masque supprime la réflexion au lieu de la modeler. Sur ces matériaux, le masque doit résider dans l’alpha de la normal map, où le générateur peut l’inscrire. Sans $envmap défini, ce paramètre ne fait également rien.]],
		[ "$basealphaenvmapmask" ] = [[Utilise l’alpha de la texture couleur comme masque de réflexion. Incompatible avec $translucent, car les deux réclament le même canal.]],
		[ "$envmapcontrast" ] = [[Renforce la réflexion. 0 la conserve telle quelle ; 1 assombrit tout sauf les points lumineux, donnant une surface plus dure et plus polie.]],
		[ "$envmapsaturation" ] = [[Règle la richesse des couleurs de la réflexion. 0 la passe en niveaux de gris ; 1 conserve toutes les couleurs de l’environnement.]],
		[ "$envmapfresnel" ] = [[Concentre la réflexion vers les angles rasants, comme une surface réelle : un sol paraît miroir au loin et terne sous les pieds. 1 applique l’effet complet.]],
		[ "$envmaplightscale" ] = [[Atténue la réflexion dans l’obscurité afin qu’une surface brillante ne luise pas dans une pièce non éclairée. 0 désactive l’effet ; 1 lie entièrement la réflexion à la lumière.]],
		[ "$envmapanisotropy" ] = [[Étire la réflexion le long de la surface, comme un métal brossé qui transforme un reflet en ligne.]],
		[ "$selfillum" ] = [[Fait briller certaines zones du matériau indépendamment de l’éclairage : écrans, yeux, runes ou métal brûlant. Par défaut, l’alpha de $basetexture place la lueur : blanc brille, noir non. Si ce canal sert déjà à la transparence, indiquez une image distincte avec $selfillummask. L’effet n’éclaire rien d’autre ; seule cette surface s’illumine.]],
		[ "$selfillummask" ] = [[Image dédiée qui indique les zones lumineuses et libère l’alpha de la texture couleur pour la transparence. Le blanc brille, le noir non.]],
		[ "$selfillumtint" ] = [[Colore les zones lumineuses. Les valeurs supérieures à 1 peuvent les rendre assez brillantes pour produire du bloom.]],
		[ "$selfillumfresnel" ] = [[Fait varier la lueur selon l’angle de vue, en la renforçant lorsque la surface se détourne. Convient aux écrans et aux yeux.]],
		[ "$selfillumfresnelminmaxexp" ] = [[Façonne cette variation angulaire : lueur minimale, lueur maximale et rapidité de la transition entre les deux.]],
		[ "$detail" ] = [[Seconde texture répétée bien plus densément que la première, qui ajoute des détails rapprochés — pores, trame du tissu ou grain du béton — trop fins pour la texture principale. Elle n’est visible que de près, ce qui est voulu : elle coûte peu et évite qu’une surface paraisse plate lorsque la caméra approche.]],
		[ "$detailscale" ] = [[Nombre de répétitions de la texture de détail sur la texture principale. 4 donne un effet discret ; 20 ou plus produit un grain fin. Une valeur excessive devient du bruit.]],
		[ "$detailblendfactor" ] = [[Intensité du détail. Commencez bas, vers 0.2 à 0.5 : le détail doit se ressentir davantage qu’il ne doit se voir.]],
		[ "$detailblendmode" ] = [[Méthode de combinaison du détail avec la couleur inférieure. 0 le multiplie et assombrit ; 1 l’ajoute et éclaircit ; 7 est le mode mod2x, où le gris moyen ne change rien et où les pixels plus clairs ou plus sombres poussent dans leur direction. Le mode 7 convient généralement au grain.]],
		[ "$detailtint" ] = [[Colore la texture de détail avant son mélange.]],
		[ "$halflambert" ] = [[Adoucit la chute de lumière pour que le côté non éclairé reste visible au lieu de devenir noir. C’est ce qui empêche les personnages de Half-Life 2 de sembler à moitié noyés dans l’ombre, et cela convient particulièrement aux modèles stylisés ou de type anime. Le coût est négligeable ; essayez-le sur tout personnage trop contrasté.]],
		[ "$lightwarptexture" ] = [[Dégradé haut d’un pixel qui redéfinit la conversion de la lumière en luminosité. Au lieu d’un ombrage lisse, le moteur consulte le dégradé de gauche (non éclairé) à droite (pleinement éclairé). Deux bandes plates donnent un cel shading net ; un dégradé chaud-froid produit plutôt un rendu pictural.]],
		[ "$notint" ] = [[Ignore la couleur appliquée à l’entité par l’outil Couleur ou par Lua, afin que ce matériau conserve toujours ses propres couleurs.]],
		[ "$receiveflashlight" ] = [[Permet à la lampe torche et aux textures projetées d’éclairer ce matériau même lorsqu’il est translucide, alors qu’elles l’ignoreraient normalement.]],
		[ "$nodecal" ] = [[Empêche les impacts de balle, le sang et les sprays d’adhérer à la surface. Lua expose le rendu des décalcomanies par prop entier, et non par sous-matériau : l’activer dans un seul emplacement les supprime donc sur tout le prop. Les décalcomanies existantes sont effacées lorsque le réglage change.]],
		[ "$basetexturetransform" ] = [[Déplace, redimensionne et fait pivoter la texture couleur sans toucher aux UV du modèle. Un Scale supérieur à 1 répète davantage la texture et la réduit ; inférieur à 1, il zoome. Translate la déplace, et 1 correspond à une tuile entière. Centre est le pivot du redimensionnement et de la rotation ; le milieu 0.5 0.5 est presque toujours correct.]],
		[ "$detailtexturetransform" ] = [[Déplace, redimensionne et fait pivoter la texture de détail. Comme $detailscale gère déjà la répétition, ce réglage sert surtout à désaligner le grain de la grille.]],
		[ "$envmapmasktransform" ] = [[Déplace, redimensionne et fait pivoter le masque de réflexion.]],
		[ "$ignorez" ] = [[Dessine la surface à travers les murs pour qu’elle soit visible depuis n’importe où sur la carte. C’est un effet de rayons X très prononcé.]],
		[ "$wireframe" ] = [[Ne dessine que les arêtes des triangles. Utile pour voir la construction d’un modèle.]],
		[ "$flat" ] = [[Ignore entièrement l’éclairage et dessine la texture à pleine luminosité.]],
		[ "$nofog" ] = [[Soustrait la surface au brouillard de la carte, afin qu’elle reste nette aux distances où tout le reste s’estompe.]],
		[ "$nolod" ] = [[Empêche le moteur de remplacer la texture par une version de résolution inférieure à distance.]],
		[ "$decal" ] = [[Traite le matériau comme une décalcomanie destinée à recouvrir une autre surface.]],
		[ "$reflectivity" ] = [[Quantité de lumière renvoyée par cette surface vers ses voisines. Ce réglage n’est utilisé qu’à la compilation d’une carte et ne fait donc rien pendant le jeu.]],
		[ "$iris" ] = [[Image de l’iris d’un œil. Avec le shader EyeRefract, elle remplace $basetexture.]],
		[ "$eyeballradius" ] = [[Courbure du globe oculaire. Une grande valeur bombe l’iris et accentue la réfraction ; une petite valeur l’aplatit.]],
		[ "$dilation" ] = [[Taille de la pupille. 0.5 est neutre ; une valeur inférieure la contracte, une valeur supérieure la dilate.]],
		[ "$glossiness" ] = [[Aspect humide de l’œil, c’est-à-dire la force du reflet sur la cornée.]],
		[ "$parallaxstrength" ] = [[Amplitude du déplacement apparent de l’iris sous la cornée lorsque la tête tourne. Cette parallaxe donne sa profondeur à l’œil.]],
		[ "$ambientocclcolor" ] = [[Couleur de l’ombre à la jonction du globe et de l’orbite, qui évite que l’œil ressemble à une bille collée au visage.]],
		[ "$treesway" ] = [[Fait plier tout le modèle sous le vent. 1 le balance autour de sa base comme un tronc ; 2 déplace chaque sommet indépendamment, ce qui convient à l’herbe et aux feuilles.]],
	},
	ru = {
		[ "$basetexture" ] = [[Основное цветное изображение поверхности — её краска, а не форма. Все остальные эффекты накладываются поверх него. Путь указывается относительно папки materials/ и без расширения: например, materials/models/kleiner/kleiner_sheet.vtf записывается как models/kleiner/kleiner_sheet. Альфа-канал используется совместно: если не указать другой источник, его читают прозрачность, маска Phong и маска отражений.]],
		[ "$frame" ] = [[Начальный кадр анимированной текстуры. Параметр действует, только если файл .vtf действительно содержит несколько кадров; для обычной текстуры он игнорируется.]],
		[ "$model" ] = [[Помечает материал как принадлежащий модели, а не геометрии карты. Редактор автоматически включает этот параметр во всём, что создаёт; отключение обычно приводит к неправильной отрисовке поверхности.]],
		[ "$surfaceprop" ] = [[Задаёт физический материал: звук и частицы при попадании, а также скользкость поверхности. Попробуйте metal, flesh, glass, wood или dirt. Это только игровое свойство, которое не меняет внешний вид.]],
		[ "$color2" ] = [[Тонирует весь материал. [1 1 1] ничего не меняет; [1 0.5 0.5] сохраняет красный и вдвое уменьшает зелёный и синий, создавая красный оттенок. Значения выше 1 осветляют. Для моделей обычно следует выбирать этот параметр: он применяется после освещения, поэтому тени остаются тенями.]],
		[ "$color" ] = [[Старый способ тонировки, применяемый до освещения, из-за чего поверхность часто выглядит выцветшей. На моделях $color2 выполняет ту же задачу лучше — используйте этот вариант, только если $color2 не действует.]],
		[ "$blendtintbybasealpha" ] = [[Ограничивает $color2 теми участками, где альфа текстуры белая. Так создаются командные цвета: нарисуйте маску в альфа-канале, и окрашиваться будет только эта область. Параметр занимает альфа-канал, поэтому несовместим с прозрачностью, которая использует альфу.]],
		[ "$blendtintcoloroverbase" ] = [[Определяет смешивание оттенка внутри маски. 0 умножает оттенок на текстуру, сохраняя детали; 1 заменяет текстуру сплошным цветом. Промежуточные значения плавно переходят между этими вариантами.]],
		[ "$desaturatewithbasealpha" ] = [[Удаляет цвет из текстуры, выбирая область по её собственному альфа-каналу. 0 ничего не меняет, 1 делает область маски чёрно-белой.]],
		[ "$translucent" ] = [[Делает поверхность полупрозрачной по альфа-каналу $basetexture: чёрная альфа невидима, белая непрозрачна, серая даёт промежуточную прозрачность. Есть проблема сортировки: движок рисует каждую полупрозрачную поверхность целиком, поэтому две такие детали одной модели могут оказаться в неверном порядке и выглядеть вывернутыми. Для волос, листьев, сетки и других жёстких краёв используйте $alphatest — он дешевле и сортируется правильно.]],
		[ "$alphatest" ] = [[Прозрачность с жёстким краем: каждый пиксель либо полностью виден, либо полностью отсутствует в зависимости от альфа-канала $basetexture. Полупрозрачных пикселей нет. Почти всегда это верный выбор для волос, листвы, решёток и вырезов в ткани: сортировка правильная, а стоимость намного ниже, чем у $translucent.]],
		[ "$alphatestreference" ] = [[Порог $alphatest. Пиксель сохраняется, если его альфа выше этого значения. Чем ниже значение, тем больше текстуры остаётся; чем выше, тем сильнее она обрезается. Обычно начинают с 0.5. Если волосы выглядят обкусанными, уменьшите к 0.3; если по краю остаётся ореол пикселей, увеличьте.]],
		[ "$allowalphatocoverage" ] = [[Смягчает жёсткий край от $alphatest с помощью игрового сглаживания. Работает, только если у игрока включено MSAA.]],
		[ "$additive" ] = [[Прибавляет материал к изображению позади него вместо перекрытия. Чёрный становится полностью невидимым, а светлые области светятся. Подходит для огня, энергии, голограмм и бликов на стекле, но не для предметов, которые должны выглядеть сплошными.]],
		[ "$alpha" ] = [[Равномерно приглушает весь материал. 1 — полностью видимый, 0 — невидимый. В отличие от $translucent параметр игнорирует альфа-канал текстуры и затемняет всё сразу.]],
		[ "$nocull" ] = [[Рисует обе стороны каждого треугольника. Включите, если односторонняя поверхность — плащ, юбка или лист — исчезает при взгляде сзади. Стоимость отрисовки этой поверхности удваивается.]],
		[ "$vertexcolor" ] = [[Позволяет цветам вершин, записанным в модели, тонировать материал. Если модель не содержит таких данных, параметр ничего не делает.]],
		[ "$vertexalpha" ] = [[Позволяет альфа-значениям вершин, записанным в модели, изменять прозрачность материала. Если модель не содержит таких данных, параметр ничего не делает.]],
		[ "$bumpmap" ] = [[Карта нормалей хранит форму поверхности в виде цвета и заставляет свет реагировать так, словно есть бугры, швы и складки, не добавляя реальную геометрию. Обычно она выглядит светлой сине-сиреневой; изображение, похожее на фотографию, картой нормалей не является. Создать её из цветной текстуры можно кнопкой «Создать». Важно знать два момента: альфа-канал по умолчанию служит маской Phong и отражений; кроме того, рельеф требует касательных данных, скомпилированных в модель. На модели без них карта нормалей не даст эффекта при любых настройках.]],
		[ "$bumpframe" ] = [[Начальный кадр анимированной карты нормалей. Для обычной одно-кадровой карты параметр игнорируется.]],
		[ "$bumptransform" ] = [[Масштабирует, вращает и сдвигает карту нормалей независимо от цветной текстуры. Используйте, чтобы мелкий рельеф повторялся чаще, чем рисунок поверхности.]],
		[ "$ssbump" ] = [[Указывает, что карта является самозатеняющей картой рельефа (SSBump) — отдельным форматом, который хранит направления света вместо углов поверхности. Включайте только для текстуры, созданной в этом формате; обычная карта нормалей получит неправильное освещение.]],
		[ "$normalmapalphaenvmapmask" ] = [[Использует альфа-канал карты нормалей вместо альфы цветной текстуры, чтобы задавать области отражений. Альфа цветной текстуры при этом освобождается для прозрачности.]],
		[ "$phong" ] = [[Включает мягкий обволакивающий блеск Source для кожи, кожи-материала, латекса и мокрых поверхностей. Это одно из самых заметных визуальных улучшений персонажа. Требует $bumpmap и без него совсем не работает. По умолчанию альфа карты нормалей задаёт места блика: белый блестит, чёрный остаётся матовым.]],
		[ "$phongboost" ] = [[Яркость блика. Для кожи обычно подходит 1–2, для полированной кожи или мокрого пластика — 5–20. Слишком большое значение заставляет всё выглядеть смазанным маслом.]],
		[ "$phongexponent" ] = [[Сосредоточенность блика. Малые значения дают широкий мягкий блеск, как у кожи; большие — маленький резкий отблеск, как у полированного металла. Попробуйте 5 для кожи, 20–40 для пластика и 60 или больше для металла. Любое значение выше 0 полностью заменяет $phongexponenttexture. Если созданная карта экспоненты ничего не меняет, установите 0, чтобы вернуть управление текстуре.]],
		[ "$phongexponenttexture" ] = [[Позволяет резкости блика меняться по поверхности вместо одного числа для всего материала. Так кожа и кожаный ремень на одном листе текстуры могут блестеть по-разному. Каналы имеют разные значения: красный задаёт резкость, зелёный — долю цвета поверхности в блике, альфа маскирует контурный свет.]],
		[ "$phongexponentfactor" ] = [[Умножает значения карты экспоненты, делая всю поверхность резче или мягче без перерисовки. Есть две ловушки: значение по умолчанию 0 означает «не используется», а не «плоско», и нормальному поведению соответствует 149, а не 1. Кроме того, параметр пришёл из Team Fortress 2 и Source 2013, поэтому здесь может игнорироваться.]],
		[ "$phongalbedotint" ] = [[Окрашивает блик цветом поверхности под ним вместо белого: красная поверхность получает красный блеск. Требует $phongexponenttexture, зелёный канал которой регулирует силу окрашивания.]],
		[ "$phongalbedoboost" ] = [[Усиливает цветную часть блика от $phongalbedotint.]],
		[ "$phongtint" ] = [[Задаёт цвет блика напрямую. [1 1 1] — белый. Тёплая кожа часто выглядит естественнее со значением вроде [1 0.8 0.7].]],
		[ "$phongfresnelranges" ] = [[Управляет изменением блеска в зависимости от угла обзора: реальные поверхности сильнее блестят при взгляде вдоль них, чем прямо. Три числа относятся к виду спереди, среднему углу и краю. [0 0.5 1] даёт естественный переход; [1 1 1] отключает угловой эффект и блестит равномерно; [0 1 0] создаёт яркую полосу посередине.]],
		[ "$phongwarptexture" ] = [[Справочное изображение, которое перекрашивает блик по мере его ослабления; используется для радужных и перламутровых покрытий.]],
		[ "$phongdisablehalflambert" ] = [[Не позволяет $halflambert смягчать блик вместе с рассеянным светом. Включите, если на материале с half-lambert блик выглядит выцветшим.]],
		[ "$basemapalphaphongmask" ] = [[Берёт маску Phong из альфа-канала цветной текстуры вместо альфы карты нормалей. Полезно, если альфа карты нормалей уже выполняет другую задачу.]],
		[ "$basemapluminancephongmask" ] = [[Предназначен для использования яркости цветной текстуры как маски Phong: светлые области блестят, тёмные нет. В Garry's Mod это не работает, поэтому изменение ничего не даст. Используйте $basemapalphaphongmask либо нарисуйте маску в альфа-канале карты нормалей через генератор.]],
		[ "$invertphongmask" ] = [[Несмотря на название, в Garry's Mod этот параметр НЕ инвертирует маску Phong. Поставляемый шейдер читает его только в коде отражений, поэтому фактически он переворачивает маску $envmap и лишь когда задан $envmap. Это удобный способ обратить маску отражений, которую нельзя перерисовать, но для заявленной в названии задачи параметр бесполезен.]],
		[ "$phongmaskcontrastbrightness" ] = [[Корректирует маску перед использованием: первое число — контраст, второе — яркость. Это параметр шейдера поверхностей карты; модели его не читают, поэтому изменение на модели не даст эффекта.]],
		[ "$rimlight" ] = [[Добавляет мягкое свечение по силуэту, словно свет огибает края. Оно отделяет персонажа от фона и часто используется в стилизованных моделях. Требует $phong. Яркость следует окружающему освещению: слабая в тёмном углу и сильная на улице.]],
		[ "$rimlightexponent" ] = [[Ширина полосы контурного света. Чем выше значение, тем ближе она к краю; чем ниже, тем дальше распространяется внутрь. Полезный диапазон — 2–8.]],
		[ "$rimlightboost" ] = [[Яркость контурного свечения. После примерно 4 персонаж начинает выглядеть горящим — иногда именно это и требуется.]],
		[ "$rimmask" ] = [[Ограничивает контурный свет альфа-каналом $phongexponenttexture, например оставляя его на коже и убирая с ткани.]],
		[ "$envmap" ] = [[Заставляет поверхность отражать окружение. Значение env_cubemap выбирает ближайшую отражающую пробу, размещённую автором карты, что почти всегда и нужно. По умолчанию отражение видно везде. Добавьте маску или включите $normalmapalphaenvmapmask, чтобы исключить участки, которые должны оставаться матовыми.]],
		[ "$envmaptint" ] = [[Сила отражения по цветовым каналам. [1 1 1] — полная сила; [0.1 0.1 0.1] — слабый блеск. Обычно сначала уменьшают именно это значение, так как полное отражение выглядит как хром.]],
		[ "$envmapmask" ] = [[Чёрно-белое изображение, задающее области отражения: белое отражает, чёрное нет. Важно: движок читает эту текстуру только на материале БЕЗ карты рельефа и БЕЗ $phong. Почти у каждой модели игрока есть оба; на ней шейдер игнорирует маску и заодно отключает $envmap, поэтому добавление маски удаляет отражение вместо его настройки. Для такого материала маска должна находиться в альфа-канале карты нормалей, куда её может записать генератор. Без заданного $envmap параметр также совершенно бесполезен.]],
		[ "$basealphaenvmapmask" ] = [[Использует альфа-канал цветной текстуры как маску отражения. Несовместим с $translucent, поскольку обоим нужен один и тот же канал.]],
		[ "$envmapcontrast" ] = [[Делает отражение глубже. 0 не меняет его; 1 затемняет всё, кроме светлых участков, отчего поверхность кажется твёрже и лучше отполированной.]],
		[ "$envmapsaturation" ] = [[Насыщенность цветов отражения. 0 делает его чёрно-белым, 1 сохраняет все цвета окружения.]],
		[ "$envmapfresnel" ] = [[Усиливает отражение к скользящим углам, как на реальной поверхности: пол вдали зеркальный, а прямо под ногами тусклый. 1 — полный эффект.]],
		[ "$envmaplightscale" ] = [[Ослабляет отражение в тёмных местах, чтобы блестящая поверхность не светилась в неосвещённой комнате. 0 отключает эффект, 1 полностью связывает отражение с освещением.]],
		[ "$envmapanisotropy" ] = [[Растягивает отражение вдоль поверхности, как шлифованный металл размазывает блик в линию.]],
		[ "$selfillum" ] = [[Заставляет части материала светиться самостоятельно, независимо от окружения: подходит для экранов, глаз, рун и раскалённого металла. По умолчанию области задаёт альфа $basetexture: белое светится, чёрное нет. Если этот канал уже используется для прозрачности, укажите отдельное изображение через $selfillummask. Эффект не освещает другие объекты — становится ярче только эта поверхность.]],
		[ "$selfillummask" ] = [[Отдельное изображение, задающее области свечения и освобождающее альфа-канал цветной текстуры для прозрачности. Белое светится, чёрное нет.]],
		[ "$selfillumtint" ] = [[Окрашивает светящиеся области. Значения выше 1 могут сделать их достаточно яркими для эффекта bloom.]],
		[ "$selfillumfresnel" ] = [[Меняет свечение в зависимости от угла обзора, усиливая его при отворачивании поверхности. Подходит для экранов и глаз.]],
		[ "$selfillumfresnelminmaxexp" ] = [[Формирует угловое ослабление: минимальное свечение, максимальное свечение и резкость перехода между ними.]],
		[ "$detail" ] = [[Вторая текстура, повторяемая намного чаще основной, добавляет мелкие детали крупного плана — поры кожи, плетение ткани или зерно бетона, для которых основной текстуре не хватает разрешения. Она заметна только вблизи, что и требуется: при низкой стоимости поверхность не становится плоской, когда камера приближается.]],
		[ "$detailscale" ] = [[Число повторов детальной текстуры поверх основной. 4 даёт мягкий эффект, 20 и больше — мелкое зерно. Слишком большое значение превращается в шум.]],
		[ "$detailblendfactor" ] = [[Сила детализации. Начните с малых значений около 0.2–0.5: детали должны скорее ощущаться, чем бросаться в глаза.]],
		[ "$detailblendmode" ] = [[Способ смешивания детальной текстуры с цветом под ней. 0 умножает и затемняет; 1 складывает и осветляет; 7 — режим mod2x, в котором средний серый не меняет поверхность, а более светлые и тёмные пиксели сдвигают её в соответствующую сторону. Для зерна обычно нужен режим 7.]],
		[ "$detailtint" ] = [[Тонирует детальную текстуру перед смешиванием.]],
		[ "$halflambert" ] = [[Смягчает спад освещения, чтобы неосвещённая сторона оставалась видимой, а не становилась чёрной. Благодаря этому персонажи Half-Life 2 не выглядят наполовину утонувшими в тени; особенно хорошо подходит стилизованным и аниме-моделям. Почти ничего не стоит, поэтому стоит попробовать на любом слишком контрастном персонаже.]],
		[ "$lightwarptexture" ] = [[Градиент высотой в один пиксель, который переопределяет превращение света в яркость. Вместо плавного затенения движок берёт значение градиента слева (нет света) направо (полное освещение). Две ровные полосы создают жёсткий cel shading, а переход от тёплого к холодному цвету — живописный вид.]],
		[ "$notint" ] = [[Игнорирует цвет, заданный объекту инструментом Colour или через Lua, поэтому материал всегда сохраняет собственные цвета.]],
		[ "$receiveflashlight" ] = [[Позволяет фонарику и проецируемым текстурам освещать этот материал, даже когда он полупрозрачен; иначе они его пропускают.]],
		[ "$nodecal" ] = [[Не даёт пулевым отверстиям, крови и спреям прилипать к поверхности. Lua управляет декалями модели по целому пропу, а не по подматериалу, поэтому включение в любом слоте подавляет декали на всём пропе. При изменении настройки существующие декали очищаются.]],
		[ "$basetexturetransform" ] = [[Сдвигает, масштабирует и вращает цветную текстуру, не меняя UV самой модели. Scale выше 1 увеличивает число повторов и уменьшает текстуру; ниже 1 приближает её. Translate сдвигает, причём 1 равен целой плитке. Centre задаёт центр масштаба и вращения; почти всегда подходит середина 0.5 0.5.]],
		[ "$detailtexturetransform" ] = [[Сдвигает, масштабирует и вращает детальную текстуру. Поскольку повторы уже задаёт $detailscale, этот параметр в основном нужен, чтобы повернуть зерно относительно сетки.]],
		[ "$envmapmasktransform" ] = [[Сдвигает, масштабирует и вращает маску отражения.]],
		[ "$ignorez" ] = [[Рисует поверхность сквозь стены, делая её видимой из любой точки карты. Это выраженный эффект рентгена, а не тонкая настройка.]],
		[ "$wireframe" ] = [[Рисует только рёбра треугольников. Полезно для просмотра устройства модели.]],
		[ "$flat" ] = [[Полностью пропускает освещение и рисует текстуру с максимальной яркостью.]],
		[ "$nofog" ] = [[Исключает поверхность из тумана карты, поэтому она остаётся резкой на расстоянии, где всё остальное исчезает.]],
		[ "$nolod" ] = [[Не позволяет движку заменять текстуру версией меньшего разрешения на расстоянии.]],
		[ "$decal" ] = [[Считает материал декалью, предназначенной для наложения поверх другой поверхности.]],
		[ "$reflectivity" ] = [[Количество света, которое поверхность отражает на соседние. Используется только при компиляции карты, поэтому во время игры ничего не меняет.]],
		[ "$iris" ] = [[Изображение радужки глаза. В шейдере EyeRefract используется вместо $basetexture.]],
		[ "$eyeballradius" ] = [[Кривизна глазного яблока. Большие значения выпячивают радужку и усиливают преломление, меньшие делают её плоской.]],
		[ "$dilation" ] = [[Размер зрачка. 0.5 — нейтральный; меньшее значение сужает, большее расширяет.]],
		[ "$glossiness" ] = [[Насколько влажным выглядит глаз — сила блика на роговице.]],
		[ "$parallaxstrength" ] = [[Насколько радужка кажется смещающейся под роговицей при повороте головы. Этот параллакс создаёт ощущение глубины глаза.]],
		[ "$ambientocclcolor" ] = [[Цвет затенения в месте соприкосновения глазного яблока и глазницы, который не даёт глазу выглядеть шариком, приклеенным к лицу.]],
		[ "$treesway" ] = [[Сгибает всю модель на ветру. 1 раскачивает её вокруг основания, как ствол дерева; 2 двигает каждую вершину отдельно, что подходит траве и листьям.]],
	},
}

AdvMat.HELP_I18N["zh-tw"] = {
    ["$additive"] = "把材質顏色加到背景上，而不是覆蓋背景。黑色會完全不可見，明亮區域會發光。適合火焰、能量、全息影像和玻璃高光，不適合應當顯得不透明的物體。",
    ["$allowalphatocoverage"] = "利用遊戲的抗鋸齒淡化 $alphatest 留下的硬邊。只有玩家啟用 MSAA 時才有效。",
    ["$alpha"] = "均勻淡化整個材質：1 完全顯示，0 完全不可見。與 $translucent 不同，它不讀取貼圖的 Alpha 通道，而是一次淡化全部內容。",
    ["$alphatest"] = "硬邊透明：由 $basetexture 的 Alpha 通道決定每個畫素完全顯示或完全消失，不存在半透明。頭髮、植物、柵格和布料鏤空幾乎都應使用它；排序正確，開銷也遠低於 $translucent。",
    ["$alphatestreference"] = "設定 $alphatest 的截斷值。畫素的 Alpha 高於此值才會保留；較低的值保留更多貼圖，較高的值裁掉更多。通常從 0.5 開始；頭髮像被啃掉時降到約 0.3，邊緣有殘留光暈時則提高。",
    ["$ambientocclcolor"] = "設定眼球與眼眶交界處的陰影顏色，避免眼睛看起來像貼在臉上的球。",
    ["$basealphaenvmapmask"] = "使用顏色貼圖的 Alpha 作為反射遮罩。它不能與 $translucent 同時使用，因為兩者都需要同一個通道。",
    ["$basemapalphaphongmask"] = "從顏色貼圖的 Alpha 而不是法線貼圖的 Alpha 讀取 Phong 遮罩。當法線貼圖 Alpha 已用於其他用途時很有用。",
    ["$basemapluminancephongmask"] = "理論上使用顏色貼圖的亮度作為 Phong 遮罩：亮區發光，暗區不發光。但它在 Garry's Mod 中不起作用，修改不會產生效果；請改用 $basemapalphaphongmask，或透過法線貼圖生成器把遮罩繪製到法線貼圖的 Alpha 通道。",
    ["$basetexture"] = "表面的主要顏色影象，也就是“油漆”而不是形狀；這裡的其他效果都會疊加在它上面。路徑從 materials/ 目錄內開始，並省略副檔名，例如 materials/models/kleiner/kleiner_sheet.vtf 應寫成 models/kleiner/kleiner_sheet。它的 Alpha 通道會被共用：除非另行指定，透明度、Phong 遮罩和反射遮罩都會讀取它。",
    ["$basetexturetransform"] = "在不改動模型 UV 的情況下平移、縮放和旋轉顏色貼圖。Scale 大於 1 會增加平鋪次數並讓貼圖變小，小於 1 則放大；Translate 用於滑動，1 代表完整移動一格；Centre 是縮放和旋轉的軸心，通常應使用中點 0.5 0.5。",
    ["$blendtintbybasealpha"] = "把 $color2 限制在貼圖 Alpha 為白色的區域。隊伍顏色通常這樣製作：在 Alpha 通道畫出遮罩，只有該區域會著色。它會佔用 Alpha 通道，因此不能與依賴 Alpha 的透明效果同時使用。",
    ["$blendtintcoloroverbase"] = "控制遮罩區域內色調與原貼圖的混合方式。0 會把色調與貼圖相乘並保留細節；1 會用純色替換貼圖；中間值在兩者之間過渡。",
    ["$bumpframe"] = "動畫法線貼圖的起始畫格。普通單畫格法線貼圖會忽略此項。",
    ["$bumpmap"] = "法線貼圖用顏色儲存表面形狀，使光線看起來遇到凹凸、接縫和皺紋，而無需增加真實幾何體。法線貼圖通常呈淺藍紫色；看起來像普通照片的影象並不是法線貼圖，可用“生成”按鈕從顏色貼圖建立。還要注意兩點：其 Alpha 通道預設充當 Phong 和反射遮罩；凹凸對映需要模型編譯時包含切線資料，缺少切線的模型無論怎樣設定都不會顯示凹凸。",
    ["$bumptransform"] = "獨立於顏色貼圖縮放、旋轉和平移法線貼圖，可用它讓細小凹凸比表面顏色更密集地平鋪。",
    ["$color"] = "較舊的著色方式，在光照前應用，因此容易讓表面顯得發白。對模型而言 $color2 通常效果更好；僅當 $color2 沒有效果時才使用它。",
    ["$color2"] = "為整個材質著色。[1 1 1] 保持原樣；[1 0.5 0.5] 保留紅色並將綠色和藍色減半，從而產生紅色色調。大於 1 的值會提亮。模型通常應使用此著色，因為它在光照後應用，陰影仍會保留。",
    ["$decal"] = "把材質視為貼花，用於覆蓋在另一個表面上。",
    ["$desaturatewithbasealpha"] = "根據貼圖自身的 Alpha 通道去除顏色。0 保持原樣，1 會把遮罩區域變成灰度。",
    ["$detail"] = "在主貼圖上更密集地平鋪第二張貼圖，以補充主貼圖解析度不足的近距離細節，例如毛孔、織物貼圖和混凝土顆粒。它只在近處明顯，這正是用途：成本很低，並能防止鏡頭靠近時表面顯得平坦。",
    ["$detailblendfactor"] = "控制細節的明顯程度。建議從 0.2–0.5 的低值開始；細節應當讓人感覺到，而不是一眼就看到。",
    ["$detailblendmode"] = "控制細節貼圖與底色的組合方式。0 為相乘，會變暗；1 為相加，會變亮；7 為 mod2x，中灰保持表面不變，更亮或更暗的畫素向相應方向調整。製作顆粒時通常應選擇 7。",
    ["$detailscale"] = "控制細節貼圖在主貼圖上重複多少次。4 較柔和，20 以上產生細顆粒；過高會變成噪點。",
    ["$detailtexturetransform"] = "平移、縮放和旋轉細節貼圖。請注意 $detailscale 已負責平鋪，因此此項主要用於旋轉顆粒、避免它與網格方向完全對齊。",
    ["$detailtint"] = "在混合前為細節貼圖著色。",
    ["$dilation"] = "控制瞳孔大小。0.5 為中性，較低會收縮，較高會擴張。",
    ["$envmap"] = "讓表面反射周圍環境。設為 env_cubemap 時會採用地圖作者放置的最近反射探針，這幾乎總是正確選擇。預設反射遍佈整個表面；新增遮罩或啟用 $normalmapalphaenvmapmask，可讓應保持啞光的部分不反射。",
    ["$envmapanisotropy"] = "沿表面方向拉伸反射，模擬拉絲金屬把高光拖成一條線。",
    ["$envmapcontrast"] = "加深反射。0 保持原樣；1 會壓暗亮點以外的部分，使表面看起來更堅硬、更光滑。",
    ["$envmapfresnel"] = "讓反射向斜視角度集中，模擬真實表面：遠處看地板像鏡子，腳下則較暗。1 為完整效果。",
    ["$envmaplightscale"] = "在暗處降低反射，避免光滑表面在無光房間裡自行發亮。0 關閉，1 讓反射完全跟隨光照。",
    ["$envmapmask"] = "用灰度圖決定反射位置：白色反射，黑色不反射。使用前請注意：引擎只會在既沒有凹凸貼圖也沒有 $phong 的材質上讀取此貼圖。大多數玩家模型兩者都有；在這種模型上，著色器會忽略此項並同時關閉 $envmap，因此新增遮罩反而會移除反射。此時遮罩必須放在法線貼圖的 Alpha 通道中，法線貼圖生成器可以寫入。若未設定 $envmap，此項也完全無效。",
    ["$envmapmasktransform"] = "平移、縮放和旋轉反射遮罩。",
    ["$envmapsaturation"] = "控制反射的色彩飽和度。0 為灰度，1 保留周圍環境的完整顏色。",
    ["$envmaptint"] = "按顏色通道控制反射強度。[1 1 1] 為全強度，[0.1 0.1 0.1] 只有輕微光澤。通常應先降低此項，因為全強度反射會像鍍鉻。",
    ["$eyeballradius"] = "控制眼球曲率。較大值讓虹膜向外鼓起並增強折射，較小值則讓它更平坦。",
    ["$flat"] = "完全跳過光照，以全亮度繪製貼圖。",
    ["$frame"] = "指定動畫貼圖從哪一畫格開始。只有 .vtf 實際包含多畫格時才有效；普通單畫格貼圖會忽略此項。",
    ["$glossiness"] = "控制眼睛看起來有多溼，也就是角膜高光的強度。",
    ["$halflambert"] = "柔化光照衰減，讓未受光的一側仍可見而不會變黑。Half-Life 2 用它避免角色像半邊陷在陰影中，尤其適合風格化和動漫模型。它幾乎沒有成本；角色對比度過強時值得嘗試。",
    ["$ignorez"] = "讓表面穿牆繪製，從地圖任何位置都能看見。這是明顯的 X 光效果，並不細微。",
    ["$invertphongmask"] = "儘管名字如此，它在 Garry's Mod 中並不會反轉 Phong 遮罩。遊戲自帶著色器只在反射程式碼中讀取此值，因此它實際反轉的是 $envmap 遮罩，而且僅在設定了 $envmap 時生效。它可免費反轉無法重畫的反射遮罩，但對其名稱所指的 Phong 遮罩沒有作用。",
    ["$iris"] = "眼睛的虹膜影象。在 EyeRefract 著色器中，它取代 $basetexture。",
    ["$lightwarptexture"] = "使用一畫素高的漸變重新定義光照如何轉為亮度。引擎不再平滑著色，而是從漸變左端（未受光）到右端（完全受光）查值。賽璐璐著色就是這樣實現：兩個平坦色帶會產生硬邊卡通光照，冷暖漸變則產生繪畫感。",
    ["$model"] = "標記此材質屬於模型而不是地圖幾何體。本編輯器建立的材質會自動啟用它；關閉後通常會導致表面算繪錯誤。",
    ["$nocull"] = "繪製每個三角形的正反兩面。當斗篷、裙子、葉片等單面表面從背面觀看會消失時啟用。這樣會使該表面的繪製開銷翻倍。",
    ["$nodecal"] = "防止彈孔、血跡和噴漆貼花附著在表面。Lua 對模型貼花的控制按整個物件而不是按子材質提供，因此在任一材質槽啟用此項都會抑制整個物件的貼花。設定變化時已有貼花會被清除。",
    ["$nofog"] = "使表面不受地圖霧影響，在其他物體隨距離淡去時仍保持清晰。",
    ["$nolod"] = "阻止引擎在遠處換用較低解析度的貼圖版本。",
    ["$normalmapalphaenvmapmask"] = "使用法線貼圖的 Alpha 通道決定反射出現的位置，而不是顏色貼圖的 Alpha。這樣顏色貼圖的 Alpha 就可以留給透明度。",
    ["$notint"] = "忽略實體透過“顏色”工具或 Lua 設定的顏色，使此材質始終保留自身顏色。",
    ["$parallaxstrength"] = "控制頭部轉動時虹膜在角膜下方看起來移動多少；這種視差會讓眼睛顯得有深度。",
    ["$phong"] = "啟用 Source 為皮膚、皮革、乳膠和潮溼表面使用的柔和包裹式高光，通常是角色模型最明顯的視覺提升。它需要 $bumpmap；沒有法線貼圖就完全無效。預設由法線貼圖的 Alpha 通道控制高光位置：白色發亮，黑色無光。",
    ["$phongalbedoboost"] = "增強由 $phongalbedotint 產生的彩色高光部分。",
    ["$phongalbedotint"] = "讓高光帶上下面表面的顏色而不是保持白色，例如紅色表面會產生紅色光澤。需要 $phongexponenttexture，其綠色通道控制著色量。",
    ["$phongboost"] = "控制高光亮度。皮膚通常約為 1–2，拋光皮革或溼塑膠約為 5–20；設得太高會讓一切看起來像塗了油。",
    ["$phongdisablehalflambert"] = "阻止 $halflambert 在柔化漫反射光的同時也柔化高光。半蘭伯特材質的高光顯得發白或模糊時啟用。",
    ["$phongexponent"] = "控制高光的集中程度。低值產生皮膚般寬而柔的光澤，高值產生拋光金屬般小而銳利的亮點。可嘗試：皮膚 5、塑膠 20–40、金屬 60 以上。這裡任何大於 0 的值都會完全覆蓋 $phongexponenttexture；若已生成指數貼圖卻看不到變化，請將此值設為 0，把控制權交還給貼圖。",
    ["$phongexponentfactor"] = "乘上指數貼圖給出的值，無需重畫即可讓整個表面的高光更銳利或更柔和。注意兩個陷阱：預設值 0 表示“未使用”，不是“平坦”；重現正常行為的值是 149 而不是 1。此外它來自 Team Fortress 2 和 Source 2013，在此處可能被完全忽略。",
    ["$phongexponenttexture"] = "讓高光緊緻度隨表面區域變化，而不是整張材質只用一個數值，因此同一貼圖表上的皮膚和皮帶可以呈現不同光澤。各通道用途不同：紅色控制緊緻度，綠色控制高光吸收多少表面顏色，Alpha 用作邊緣光遮罩。",
    ["$phongfresnelranges"] = "控制高光隨觀察角度的變化；真實表面在斜視時通常比正視時更亮。三個數值依次對應正面、中間角度和邊緣。[0 0.5 1] 是自然衰減，[1 1 1] 關閉角度變化並均勻發亮，[0 1 0] 會在中間形成明顯亮帶。",
    ["$phongmaskcontrastbrightness"] = "在使用遮罩前進行調整：第一個數值是對比度，第二個是亮度。這是筆刷著色器引數，模型不會讀取它，因此在模型上修改不會產生效果。",
    ["$phongtint"] = "直接設定高光顏色。[1 1 1] 為白色；暖色皮膚通常使用類似 [1 0.8 0.7] 的值更自然。",
    ["$phongwarptexture"] = "使用查詢貼圖在高光衰減過程中重新著色，適合虹彩和珍珠質表面。",
    ["$receiveflashlight"] = "允許手電筒和投射貼圖照亮此材質，即使它是半透明的；否則這些光源會跳過它。",
    ["$reflectivity"] = "控制此表面向周圍反彈多少光。它只在編譯地圖時使用，因此執行遊戲時修改沒有效果。",
    ["$rimlight"] = "在輪廓周圍新增柔和光暈，彷彿光線繞過邊緣，可讓角色從背景中突出，常用於風格化模型。需要 $phong。亮度跟隨環境光，因此暗角中較弱、戶外較強。",
    ["$rimlightboost"] = "控制邊緣光亮度。超過約 4 時角色會開始像著火一樣——有時這正是想要的效果。",
    ["$rimlightexponent"] = "控制邊緣光帶的寬窄。值越高越貼近輪廓，越低則向內部擴散；2–8 通常最實用。",
    ["$rimmask"] = "使用 $phongexponenttexture 的 Alpha 通道限制邊緣光，例如讓皮膚髮亮而布料不發亮。",
    ["$selfillum"] = "讓材質的部分割槽域自行發光並忽略周圍光照，適合螢幕、眼睛、符文和熾熱金屬。預設由 $basetexture 的 Alpha 決定位置：白色發光，黑色不發光。若該通道已用於透明度，請用 $selfillummask 指向單獨影象。它不會照亮其他物體，只會提亮自身表面。",
    ["$selfillumfresnel"] = "讓發光隨觀察角度變化，表面轉離視線時會增強。適合螢幕和眼睛。",
    ["$selfillumfresnelminmaxexp"] = "塑造上述角度衰減：三個數值分別控制最小亮度、最大亮度，以及兩者之間過渡的銳利程度。",
    ["$selfillummask"] = "用獨立影象指定發光區域，從而把顏色貼圖的 Alpha 留給透明度。白色發光，黑色不發光。",
    ["$selfillumtint"] = "設定發光區域的顏色。大於 1 的值可將亮度推高到產生泛光。",
    ["$ssbump"] = "宣告該法線貼圖是自陰影凹凸貼圖（SSBump）：它儲存光照方向而不是表面角度，格式不同。只有貼圖本來就是按此格式製作時才啟用；對普通法線貼圖啟用會使光照異常。",
    ["$surfaceprop"] = "指定物理材質：被射擊時的聲音和粒子，以及表面的摩擦程度。可嘗試 metal、flesh、glass、wood、dirt。它隻影響遊戲行為，不會改變外觀。",
    ["$translucent"] = "使用 $basetexture 的 Alpha 通道讓表面半透明：黑色 Alpha 完全不可見，白色完全不透明，灰色介於兩者之間。注意排序問題：引擎把每個半透明表面作為整體繪製，同一模型的多個半透明部件可能順序錯誤並呈現“裡外顛倒”。頭髮、樹葉、鐵絲網等硬邊緣物件應改用 $alphatest；它開銷更低且排序正確。",
    ["$treesway"] = "讓整個模型隨風彎曲。1 會像樹幹一樣繞根部擺動；2 會讓每個頂點獨立擺動，更適合草和樹葉。",
    ["$vertexalpha"] = "允許模型中預先繪製的頂點透明度淡化材質。模型沒有這種資料時不會產生效果。",
    ["$vertexcolor"] = "允許模型中預先繪製的頂點顏色為材質著色。模型沒有頂點顏色時不會產生效果。",
    ["$wireframe"] = "只繪製三角形的邊，可用於檢視模型的網格結構。",
}
